window.PFG_SCENES = [{"id":"milky-way","title":"Milky Way","category":"night","description":"Give the stars a clear shape and the landscape a reason to be there.","tags":["stars","astro","11mm","dark sky"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/1.8–2","shutter":"6–10 s","iso":"1600–3200","focus":"MF · magnified bright star"},"lens":"Your Sony 11mm f/1.8; actual APS-C focal length.","support":"Stable tripod; 2-second timer or remote.","why":"These starting ranges suit an untracked wide view under a dark sky. A short exposure limits star elongation; the wide aperture gathers light without making the sky excessively bright.","steps":["Frame before darkness; keep intrusive lamps outside the composition.","Magnify a bright star and adjust until its centre is smallest, then take a test.","Inspect stars enlarged; shorten exposure if elongated, then adjust ISO for a useful result."],"composition":["Give one tree, ridge or building a clear silhouette beneath the sky.","Move until the bright band connects with your foreground subject."],"pack":["Tripod","Remote or timer","Spare battery","Lens cloth"],"fixes":[{"problem":"Stars stretch","solution":"Shorten the shutter; verify focus separately."},{"problem":"Foreground disappears","solution":"Make a separate longer foreground exposure without moving the camera."},{"problem":"Misty star halos","solution":"Check the lens for dew before changing focus or sharpening."}],"sony":"Use Focus Magnifier; the infinity endpoint is not a reliable focus setting. Turn SteadyShot Off on the tripod.","fullFrame":"Use roughly 16–17mm for similar framing; reassess shutter duration at your sensor resolution.","phone":"Tripod night mode may show the band; detail depends strongly on sky brightness and processing.","sources":[{"label":"Sony: photographing the night sky","url":"https://www.sony.com.my/electronics/support/articles/00223374"},{"label":"PhotoPills: Milky Way settings and NPF","url":"https://www.photopills.com/articles/milky-way-photography-settings"}]},{"id":"star-trails","title":"Star trails","category":"night","description":"Build the sky's movement from a continuous sequence of short photographs.","tags":["stars","stacking","interval","11mm"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/2.8–4","shutter":"10–20 s per frame","iso":"400–1600","focus":"MF · magnified star"},"lens":"Your 11mm, or 16mm on your 16–55mm; actual APS-C lengths.","support":"Tripod; interval shooting; leave the camera untouched.","why":"Repeated frames let you reject interruptions and combine the remaining trails later. These starting ranges need adjustment for moonlight and light pollution before committing to a long sequence.","steps":["Compose and focus; test until bright stars retain colour and the foreground is controlled.","Fix exposure and white balance; disable Long Exposure NR for the sequence.","Set the interval just longer than exposure and capture 30–90 minutes for stacking."],"composition":["Face the north celestial pole for circles around a stable centre.","Keep a recognisable silhouette below the trails and clear of their centre."],"pack":["Tripod","Charged batteries or USB power","Empty memory card","Dew protection"],"fixes":[{"problem":"Gaps in trails","solution":"Reduce dead time and check for skipped frames or noise-reduction waits."},{"problem":"Sky washes out","solution":"Reduce per-frame exposure or ISO before restarting the series."},{"problem":"Focus drifts","solution":"Check for dew and avoid touching the lens during capture."}],"sony":"Shooting Interval is start-to-start: a 10-second exposure plus a 1-second gap needs an 11-second interval.","fullFrame":"Match framing with a longer actual focal length; determine brightness from a test sequence.","phone":"A dedicated star-trail mode may work; ordinary night mode does not create a controlled long sequence.","sources":[{"label":"Sony a6700: Interval Shoot Func.","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0407P_interval_shoot_setting.html"},{"label":"Sony a6700: Long Exposure NR","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_long_exposure_nr.html"}]},{"id":"moon-close-up","title":"Moon close-up","category":"night","description":"Record lunar texture with a bright-subject exposure and enough focal length.","tags":["moon","telephoto","craters","tripod"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/5.6–8","shutter":"1/250–1/500 s","iso":"100–400","focus":"MF magnified crater · or AF-S Spot"},"lens":"300–600mm actual APS-C focal length; an additional telephoto or correctly adapted telescope is required.","support":"Rigid tripod and head; remote or timer.","why":"The sunlit Moon is bright even against a black sky. These starting settings suit a bright lunar phase; the fast shutter reduces vibration while a long lens supplies useful image scale.","steps":["Find the Moon with a wider view, then tighten framing without clipping its edge.","Focus on a high-contrast crater boundary and check an enlarged test.","Protect bright lunar detail; shoot several frames and select the crispest."],"composition":["A partial phase reveals relief near the light-to-shadow boundary.","Leave breathing room around the disc rather than trimming its edge."],"pack":["Long lens or telescope adapter","Tripod","Remote","Lens hood"],"fixes":[{"problem":"White blank disc","solution":"Shorten exposure; do not let the surrounding black sky dictate brightness."},{"problem":"Wavering details","solution":"Avoid views over warm roofs and wait for steadier air."},{"problem":"Tiny Moon","solution":"Use longer optics; the 16–55mm cannot produce a detailed close-up."}],"sony":"Use Focus Magnifier to inspect crater detail. Turn SteadyShot Off on a stable tripod.","fullFrame":"The same lens produces a smaller disc in the frame; exposure needs no crop-factor correction.","phone":"Use an optical telephoto if available; digital magnification cannot recover absent lunar detail.","sources":[{"label":"Nikon: photographing the Moon","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/how-to-photograph-the-moon"},{"label":"Sony a6700: SteadyShot","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_still_image_steadyshot.html"}]},{"id":"moon-in-landscape","title":"Moon in a landscape","category":"night","description":"Balance a small lunar disc with a meaningful landscape in twilight.","tags":["moon","twilight","landscape","bracketing"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/5.6–8","shutter":"1/30–1/250 s · bright twilight","iso":"100–400","focus":"AF-S distant subject · verify Moon"},"lens":"Your 16–55mm; 35–55mm gives the Moon more presence than 11mm.","support":"Tripod for matched frames and changing twilight.","why":"Twilight can bring the landscape and Moon closer in brightness. These starting ranges favour lunar detail; darker foregrounds may need a separate bracketed exposure.","steps":["Find an alignment while there is still colour and light in the landscape.","Expose a test for the Moon and inspect its bright surface.","If the land is too dark, bracket from the same position without changing focal length."],"composition":["Place the Moon near a roofline or tree without an accidental edge collision.","Step farther from the foreground and use a longer lens for stronger alignment."],"pack":["Tripod","16–55mm lens","Remote or timer","Lens cloth"],"fixes":[{"problem":"Moon burns white","solution":"Shorten the lunar exposure; recover the land using another frame if needed."},{"problem":"Land is a silhouette","solution":"Shoot earlier in twilight or deliberately keep the graphic silhouette."},{"problem":"Both subjects cannot focus","solution":"Increase foreground distance or capture separate focus frames."}],"sony":"Review the captured histogram; live-view brightness alone can mislead in low light.","fullFrame":"Use roughly 50–85mm for similar framing; keep the same position to preserve the alignment.","phone":"Expose for the Moon if its shape matters; automated night mode may turn it into a bright patch.","sources":[{"label":"Nikon: Moon and foreground exposure","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/how-to-photograph-the-moon"},{"label":"Sony a6700: histogram display","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/201h_histogram.html"}]},{"id":"aurora","title":"Aurora","category":"night","description":"Preserve the moving curtains instead of averaging them into a luminous cloud.","tags":["aurora","northern lights","11mm","night"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/1.8–2.8","shutter":"1–6 s","iso":"800–3200","focus":"MF · magnified bright star"},"lens":"Your 11mm f/1.8; use 16mm on the zoom for a smaller distant display.","support":"Stable tripod; remote or short self-timer.","why":"The aurora moves as well as changing brightness. These starting ranges suit visible, active curtains; shorter exposures preserve structure while faint diffuse displays may need longer tests.","steps":["Focus on a star, then take a short exposure of the strongest visible structure.","Inspect curtain edges and highlights; shorten the shutter when movement smears them.","Adjust ISO as brightness changes and reframe when the display moves overhead."],"composition":["Use a dark ridge or lone tree to establish scale without crowding the sky.","Try a vertical frame when rays reach overhead and horizontal for broad arcs."],"pack":["Tripod","Spare battery","Warm gloves","Lens cloth"],"fixes":[{"problem":"Green featureless patch","solution":"Shorten exposure and check whether bright colour channels are clipping."},{"problem":"Faint display","solution":"Open the aperture; extend duration only while useful structure remains."},{"problem":"Soft stars","solution":"Refocus with magnification and inspect the front element for condensation."}],"sony":"Use manual focus and fixed white balance for consistent sequences; turn SteadyShot Off on the tripod.","fullFrame":"Use about 16mm for equivalent framing; retain shutter timing based on the aurora's movement.","phone":"Tripod night mode can reveal colour, but long automatic captures may smear fast curtains.","sources":[{"label":"Canon: photographing auroras","url":"https://www.usa.canon.com/learning/training-articles/training-articles-list/photographing-auroras"},{"label":"Sony: night-sky focusing","url":"https://www.sony.com.my/electronics/support/articles/00223374"}]},{"id":"meteor-shower","title":"Meteor shower","category":"night","description":"Give unexpected meteors plenty of chances to cross a well-composed frame.","tags":["meteors","stars","interval","11mm"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/1.8–2","shutter":"6–10 s","iso":"1600–3200","focus":"MF · magnified star"},"lens":"Your 11mm f/1.8 gives wide coverage with a bright aperture.","support":"Tripod; repeated exposures with minimal gaps.","why":"A meteor may cross in a fraction of a second, so a wide aperture helps record its brief light. These dark-sky starting ranges keep surrounding stars compact while a sustained sequence improves your chances.","steps":["Choose a clear dark area of sky with a simple foreground and focus carefully.","Test exposure, then lock settings and turn Long Exposure NR Off.","Run repeated frames with a short gap; inspect periodically for dew without moving the camera."],"composition":["Include enough sky for an unexpected trail to have room.","Keep one low foreground shape; bright lamps can overwhelm a faint meteor."],"pack":["Tripod","Charged battery or USB power","Memory card","Lens cloth"],"fixes":[{"problem":"No meteors recorded","solution":"Extend the observing session; activity and placement are unpredictable."},{"problem":"Sky too bright","solution":"Shorten each frame or lower ISO while keeping the aperture open."},{"problem":"Long gaps","solution":"Check start-to-start interval, write delays and noise-reduction settings."}],"sony":"An 8-second exposure with a 1-second gap needs a 9-second Shooting Interval; confirm frames complete.","fullFrame":"Choose a similarly wide view; set shutter using enlarged star checks for that camera and lens.","phone":"Meteor capture is possible but unreliable; automated stacking may discard or soften brief trails.","sources":[{"label":"Nikon: photographing meteor showers","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/photographing-meteors-fireballs-and-meteor-showers"},{"label":"Sony a6700: interval shooting","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0407P_interval_shoot_setting.html"}]},{"id":"night-landscape","title":"Moonlit landscape","category":"night","description":"Let moonlight reveal terrain while keeping a believable night-time atmosphere.","tags":["moonlight","landscape","night","tripod"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/2.8–4","shutter":"4–10 s","iso":"400–1600","focus":"MF magnified distant detail"},"lens":"Your 11mm or 16–24mm on the 16–55mm; actual APS-C focal lengths.","support":"Tripod; remote or 2-second timer.","why":"Moonlight can supply useful shape and texture without artificial lighting. These starting ranges suit a visibly moonlit landscape; check both land and sky rather than making the scene look like daylight.","steps":["Find side light on the terrain and keep direct lamps outside the frame.","Focus on a distant illuminated feature, or a star when the horizon is too dark.","Make a test and adjust duration for the land, checking stars if they must remain points."],"composition":["Use moonlit edges to separate a ridge or tree from its background.","Leave some deep shadow so the scene retains depth and night atmosphere."],"pack":["Tripod","Remote or timer","Lens hood","Spare battery"],"fixes":[{"problem":"Foreground noise","solution":"Give the static foreground a longer separate exposure if stars limit the main frame."},{"problem":"Scene looks like noon","solution":"Reduce exposure and judge with a dimmer screen."},{"problem":"Leaves smear","solution":"Shorten exposure, open aperture or wait for the wind to settle."}],"sony":"Setting Effect ON reflects exposure settings; inspect playback because night live view is only a guide.","fullFrame":"Use approximately 16–35mm for the same view; exposure is still governed by actual moonlight.","phone":"Brace the phone and use night mode; moving foliage may look smeared or inconsistent.","sources":[{"label":"Canon: Milky Way and night-sky photography","url":"https://www.usa.canon.com/learning/training-articles/training-articles-list/into-the-night-photographing-the-milky-way-and-night-sky"},{"label":"Sony a6700: Live View Display Set.","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_live_view_disp_set.html"}]},{"id":"light-painting","title":"Light painting","category":"night","description":"Reveal a stationary subject with a controlled sweep of light during exposure.","tags":["torch","creative","long exposure","night"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/5.6–8","shutter":"10–20 s","iso":"100–400","focus":"AF-S illuminated subject · then MF"},"lens":"Your 16–55mm at 16–35mm; use 11mm only when the surroundings contribute.","support":"Tripod; timer or remote; consistent camera position.","why":"The shutter provides working time while the torch supplies the subject's light. These starting ranges suit a dark static scene; brightness also depends on torch power, distance and dwell time.","steps":["Illuminate the subject to focus, then switch to MF without moving the camera.","Start exposure and sweep a diffused torch across the subject from one side.","Review bright patches and repeat, changing only the sweep or exposure between attempts."],"composition":["Side light reveals texture more clearly than lighting from the camera position.","Keep the subject separate from a dark background and leave space around its outline."],"pack":["Tripod","Torch with diffuser","Remote or timer","Spare battery"],"fixes":[{"problem":"Hot white patches","solution":"Move the torch continuously, reduce power or spend less time on bright surfaces."},{"problem":"Your body appears","solution":"Stay out of the beam and avoid pausing in illuminated areas."},{"problem":"Background too bright","solution":"Shorten exposure while preserving enough time to complete the sweep."}],"sony":"Turn SteadyShot Off on the tripod; use manual focus after acquiring the illuminated subject.","fullFrame":"Match framing with focal length; expose for the actual lighting without crop-factor correction.","phone":"Manual long-exposure apps may work; standard night stacking can render moving light unpredictably.","sources":[{"label":"Sony: manual exposure and Bulb","url":"https://www.sony.com/electronics/support/articles/00267933"},{"label":"Sony a6700: SteadyShot","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_still_image_steadyshot.html"}]},{"id":"blue-hour-stars","title":"First stars at blue hour","category":"night","description":"Catch the brief balance between a coloured sky, readable land and the first stars.","tags":["blue hour","twilight","stars","landscape"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/2–2.8","shutter":"1–6 s","iso":"400–1600","focus":"MF star or distant detail"},"lens":"Your 11mm f/1.8, or 16mm f/2.8 on the 16–55mm.","support":"Tripod and short self-timer; repeat as twilight changes.","why":"The scene changes quickly as daylight fades and bright stars emerge. These ranges are a starting point for late twilight; a vivid blue sky may still hide most stars.","steps":["Compose while the ground is visible and identify one distant subject.","Take a test as the first bright stars appear; avoid pushing the sky to pale blue.","Repeat every few minutes, adjusting exposure and checking star shape as darkness increases."],"composition":["Use a small warm window or lamp as an accent against the blue sky.","Keep a clean horizon so sparse stars remain easy to notice."],"pack":["Tripod","11mm or 16–55mm lens","Remote or timer","Lens cloth"],"fixes":[{"problem":"No stars appear","solution":"Wait for darker twilight; increasing exposure also brightens the sky."},{"problem":"Lamps lose colour","solution":"Reduce exposure or bracket a shorter frame for the lights."},{"problem":"Ground turns noisy","solution":"Capture a brighter foreground frame earlier, preserving the same composition."}],"sony":"Use fixed white balance for comparisons and review the recorded histogram, not screen brightness alone.","fullFrame":"Use 16–24mm for similar framing; retest as the scene darkens.","phone":"Night mode balances twilight, but automatic processing may discard faint stars.","sources":[{"label":"Sony: photographing the night sky","url":"https://www.sony.com.my/electronics/support/articles/00223374"},{"label":"Sony a6700: histogram display","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/201h_histogram.html"}]},{"id":"tracked-milky-way","title":"Tracked Milky Way","category":"night","description":"Collect more sky light with a tracker and photograph the stationary foreground separately.","tags":["tracker","Milky Way","stacking","11mm"],"difficulty":"Advanced","settings":{"mode":"M","aperture":"f/2–2.8","shutter":"30–60 s · test tracking","iso":"400–1600","focus":"MF · magnified star"},"lens":"Your 11mm or 16mm on the zoom; an additional star tracker is required.","support":"Rigid tripod, tracker and secure head; follow the tracker's alignment procedure.","why":"Tracking compensates for apparent sky movement so longer frames can collect more light. These ranges assume successful alignment; the stationary landscape will move relative to the tracked sky.","steps":["Set up and align the tracker according to its instructions, then focus on a star.","Test at 30 seconds; inspect centre and edge stars before extending duration.","Capture a sky sequence, then switch tracking off and expose the foreground separately."],"composition":["Choose a clean skyline that makes a careful sky-to-land blend practical.","Keep the framing generous because alignment and blending may require a crop."],"pack":["Tracker and power","Tripod","Remote with Bulb support","Lens cloth"],"fixes":[{"problem":"Stars trail","solution":"Check alignment, head movement and tracking operation; shorten the next test."},{"problem":"Foreground blurs","solution":"Capture an untracked foreground; tracking cannot hold sky and land simultaneously."},{"problem":"Sky becomes pale","solution":"Reduce duration or ISO while checking bright-star colour."}],"sony":"For exposures beyond 30 seconds, select M/Bulb and Mechanical Shutter; turn built-in interval shooting Off. Use BULB Timer or a compatible remote and repeat. Turn SteadyShot Off.","fullFrame":"Match framing, then test tracking at your chosen focal length and resolution.","phone":"Manual control and a secure tracker mount are needed; ordinary night mode is simpler.","sources":[{"label":"Canon: astrophotography and tracking tradeoffs","url":"https://www.canon.ca/en/Articles/2024/astrophotography-tips"},{"label":"Sony: manual exposure and Bulb","url":"https://www.sony.com/electronics/support/articles/00267933"},{"label":"Sony a6700: Bulb prerequisites","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0302C_bulb.html"},{"label":"Sony a6700: BULB Timer Settings","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_bulb_timer.html"}]},{"id":"perched-bird","title":"Perched bird","category":"wildlife","description":"Prioritise a crisp eye and a clean background while the bird briefly holds still.","tags":["birds","telephoto","perch","eye focus"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/4–6.3 · lens permitting","shutter":"1/500–1/1000 s","iso":"Auto · inspect chosen value","focus":"AF-C · Bird · Tracking: Spot M"},"lens":"200–600mm actual APS-C focal length; additional telephoto needed for small distant birds.","support":"Handheld with support, monopod or stable tripod.","why":"Even a perched bird can flick its head faster than stabilisation can help. These starting ranges preserve small movements while Auto ISO follows changing light.","steps":["Find a position with a distant uncluttered background and stay still.","Place the tracking spot over the head and wait for an unobstructed eye.","Shoot a short burst, then inspect the eye and adjust shutter if movement remains."],"composition":["Leave space in the direction the bird looks.","Keep branches from crossing the face; move your position before waiting."],"pack":["Telephoto lens","Lens hood","Support","Spare battery"],"fixes":[{"problem":"Eye is soft","solution":"Confirm focus lands on the eye, then increase shutter if it moved."},{"problem":"Background attracts focus","solution":"Use a smaller spot on the head and reacquire the bird."},{"problem":"High ISO","solution":"Wait for better light or open aperture; slow shutter only when the bird settles."}],"sony":"Enable Subject Recog in AF and select Bird; keep AF-C for small movements.","fullFrame":"Use more focal length or accept looser framing; preserve a shutter suitable for the bird.","phone":"Use optical reach and stay back; heavy digital cropping quickly removes feather detail.","sources":[{"label":"Sony a6700: bird autofocus examples","url":"https://support.d-imaging.sony.co.jp/support/tutorial/ilc/ilce-6700/en/05.php"}]},{"id":"bird-in-flight","title":"Bird in flight","category":"wildlife","description":"Track smoothly and give fast movement enough shutter speed before worrying about ISO.","tags":["birds","flight","action","telephoto"],"difficulty":"Advanced","settings":{"mode":"M + Auto ISO","aperture":"f/4–6.3 · lens permitting","shutter":"1/1600–1/3200 s","iso":"Auto · check available light","focus":"AF-C · Bird · Tracking: Zone"},"lens":"100–400mm actual APS-C focal length; additional telephoto zoom required.","support":"Handheld or a freely moving supported head.","why":"Changing distance demands continuous focus while fast wings need short exposures. These daylight starting ranges suit larger birds; smaller fast birds may need more speed.","steps":["Start at a wider zoom setting and acquire the bird before pressing fully.","Pan smoothly with its body and keep tracking through a short burst.","Inspect eye sharpness and wing position; adjust shutter and framing for the next pass."],"composition":["Leave room ahead of the bird and around fully extended wings.","Look for separation between the body and a simple sky or distant background."],"pack":["Telephoto zoom","Lens hood","Charged battery","Fast memory card"],"fixes":[{"problem":"Bird leaves the frame","solution":"Zoom out, acquire earlier and tighten only after tracking is stable."},{"problem":"Wings smear","solution":"Increase shutter; accept the required ISO or choose intentional motion."},{"problem":"Bird is too dark","solution":"Raise exposure compensation cautiously while checking bright plumage."}],"sony":"Enable Subject Recog in AF and Bird; start with Tracking: Zone for larger flying birds.","fullFrame":"Match image scale with focal length; shutter is still governed by movement, not crop factor.","phone":"Wide contextual flight shots are realistic; small distant birds challenge focus and optical reach.","sources":[{"label":"Sony a6700: bird autofocus examples","url":"https://support.d-imaging.sony.co.jp/support/tutorial/ilc/ilce-6700/en/05.php"}]},{"id":"garden-birds","title":"Garden birds at a perch","category":"wildlife","description":"Prepare the light and background, then wait for the bird to complete the photograph.","tags":["garden","birds","perch","remote"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/4–6.3 · lens permitting","shutter":"1/800–1/1600 s","iso":"Auto · monitor in shade","focus":"AF-C · Bird · Tracking: Spot M"},"lens":"150–400mm actual APS-C focal length; your 55mm suits a wider environmental view.","support":"Tripod or beanbag from a settled observation position.","why":"A predictable perch lets you solve composition before each visit. These starting settings allow for head movement and hops; a tripod cannot freeze the bird.","steps":["Choose a safe existing perch with soft side light and a distant background.","Position the focus area where the head is likely to appear.","Wait quietly; take short bursts when the eye is visible and the pose opens."],"composition":["Use camera height to place sky or distant greenery behind the bird.","Include enough perch to explain the pose without letting it dominate."],"pack":["Telephoto if available","Tripod or beanbag","Lens hood","Spare battery"],"fixes":[{"problem":"Window reflections","solution":"Shoot through an open window when possible; glass can reduce contrast and sharpness."},{"problem":"Bird too small","solution":"Use longer optics or keep a deliberate wider garden composition."},{"problem":"Busy background","solution":"Change camera height or position before the next visit."}],"sony":"Select Bird recognition and AF-C; use Spot M when branches repeatedly distract tracking.","fullFrame":"Use additional focal length for the same bird size or allow more garden around it.","phone":"A predictable close perch helps; avoid disrupting visits by approaching too closely.","sources":[{"label":"Sony a6700: perched-bird focusing","url":"https://support.d-imaging.sony.co.jp/support/tutorial/ilc/ilce-6700/en/05.php"}]},{"id":"waterbirds","title":"Waterbirds and reflections","category":"wildlife","description":"Combine a sharp bird with a reflection or a clean pattern of ripples.","tags":["birds","water","reflections","wildlife"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/5.6–8","shutter":"1/800–1/1600 s","iso":"Auto · review white feathers","focus":"AF-C · Bird · Tracking: Spot M"},"lens":"70–300mm actual APS-C focal length; 55mm suits a close large bird with context.","support":"Handheld or low supported position on firm ground.","why":"Swimming birds change distance while reflections and bright plumage challenge exposure. These daylight ranges favour detail and modest movement; splashing wings may require faster shutter.","steps":["Choose clear water behind the bird and focus on its head.","Check a test for clipped white feathers; reduce exposure compensation if detail disappears.","Follow the bird smoothly and photograph a clean head angle or complete reflection."],"composition":["Get lower for an intimate eye-level view while keeping safe footing.","Include the whole reflection or crop it deliberately rather than clipping it accidentally."],"pack":["Telephoto if needed","Lens hood","Ground pad","Lens cloth"],"fixes":[{"problem":"White feathers burn out","solution":"Reduce exposure and check feather texture in playback."},{"problem":"Reflection breaks up","solution":"Wait for calmer water or make the ripples part of the picture."},{"problem":"Splashing wings blur","solution":"Increase shutter to suit the action and allow ISO to rise."}],"sony":"Reacquire the head with a smaller spot if water or other birds distract tracking.","fullFrame":"Use focal length for your preferred subject size; exposure still follows feathers and available light.","phone":"Large nearby waterbirds and reflections are practical subjects; avoid excessive digital zoom.","sources":[{"label":"Sony a6700: birds and obstacles","url":"https://support.d-imaging.sony.co.jp/support/tutorial/ilc/ilce-6700/en/05.php"},{"label":"Sony a6700: histogram display","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/201h_histogram.html"}]},{"id":"wildlife-portrait","title":"Wildlife portrait","category":"wildlife","description":"Make the animal's expression clear while allowing its surroundings to support the story.","tags":["animals","portrait","telephoto","eye focus"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/4–6.3 · lens permitting","shutter":"1/500–1/1000 s","iso":"Auto · check light level","focus":"AF-C · Animal · Tracking: Spot M"},"lens":"100–400mm actual APS-C focal length; additional telephoto required for distance.","support":"Handheld, monopod or quiet supported position.","why":"The eye anchors a portrait even when the animal barely moves. These starting ranges balance small movements with separation; ensure sufficient depth of field for important features.","steps":["Settle at an appropriate distance and choose a clear sightline through nearby vegetation.","Place the tracking area over the head and watch the visible eye.","Wait for an expressive pause, then check both focus placement and motion in playback."],"composition":["Keep empty space toward the animal's gaze.","Include characteristic habitat when it adds information rather than visual clutter."],"pack":["Telephoto lens","Lens hood","Support","Spare battery"],"fixes":[{"problem":"Nose sharp, eye soft","solution":"Reacquire the eye; narrow aperture if more facial depth is needed."},{"problem":"Grass steals focus","solution":"Use a small spot on a clear feature or adjust your sightline."},{"problem":"Animal fills frame too tightly","solution":"Zoom out and leave space for ears, movement and context."}],"sony":"Select Animal; detection can fail on obscured or partly framed heads.","fullFrame":"Use longer focal length for similar framing; choose aperture for the required depth of field.","phone":"Use environmental portraits of accessible animals; do not compensate for limited reach by crowding wildlife.","sources":[{"label":"Sony a6700: animal focusing examples","url":"https://support.d-imaging.sony.co.jp/support/tutorial/ilc/ilce-6700/en/05.php"},{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"}]},{"id":"running-animal","title":"Running animal","category":"wildlife","description":"Prepare for changing distance and capture a purposeful stride with a sharp face.","tags":["animals","action","running","tracking"],"difficulty":"Advanced","settings":{"mode":"M + Auto ISO","aperture":"f/4–5.6 · lens permitting","shutter":"1/1600–1/3200 s","iso":"Auto · bright light helps","focus":"AF-C · Animal · Tracking: Zone"},"lens":"70–300mm actual APS-C focal length; your 16–55mm suits nearby pets in wider scenes.","support":"Handheld or a support that allows free tracking.","why":"Running changes both position and focus distance rapidly. These starting ranges favour action; a fast shutter matters more than low ISO when the animal will not pause.","steps":["Choose a predictable clear path and acquire the animal before the best position.","Track the head smoothly while making short bursts through the movement.","Review face detail and stride shape, then adjust shutter or framing for the next opportunity."],"composition":["Leave room in front for the animal to run into.","Try a lower viewpoint to separate the body from the ground."],"pack":["Suitable zoom","Lens hood","Charged battery","Fast memory card"],"fixes":[{"problem":"Focus lags behind","solution":"Acquire earlier, keep continuous focus active and choose a less obstructed route."},{"problem":"Feet blur excessively","solution":"Increase shutter or accept a deliberate movement effect."},{"problem":"Framing loses ears or paws","solution":"Zoom out before the run and leave generous margins."}],"sony":"Enable Subject Recog in AF and Animal; inspect results because tracking cannot guarantee every frame.","fullFrame":"Match framing with focal length; retain shutter according to speed and intended effect.","phone":"Good light and a predictable path help; use burst capture and avoid night mode for action.","sources":[{"label":"Sony a6700: animal tracking examples","url":"https://support.d-imaging.sony.co.jp/support/tutorial/ilc/ilce-6700/en/05.php"},{"label":"Sony a6700: subject recognition limits","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_about_eye_af.html"}]},{"id":"pet-portrait","title":"Pet portrait","category":"wildlife","description":"Meet the pet at eye level and let soft light reveal its expression.","tags":["pet","dog","cat","portrait","16–55mm"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/250–1/500 s","iso":"Auto · window light preferred","focus":"AF-C · Animal · eye"},"lens":"Your 16–55mm at 35–55mm; actual APS-C focal lengths.","support":"Handheld at the pet's eye level.","why":"A comfortable pet gives more natural expressions than one held in an awkward pose. These starting settings suit a calm subject in soft light, with enough shutter speed for small head movements.","steps":["Place yourself near soft window light or open shade with a quiet background.","Focus on the nearer eye and wait for a brief attentive expression.","Check eye and nose detail, then adjust aperture if facial depth is too shallow."],"composition":["Lower the camera instead of looking down from standing height.","Keep a little room around ears and choose a background that separates fur colour."],"pack":["16–55mm lens","Favourite toy","Clean background","Lens cloth"],"fixes":[{"problem":"Nose dominates","solution":"Step back and use the longer end of the zoom."},{"problem":"Eyes hide in dark fur","solution":"Turn the pet toward softer light rather than lifting all shadows heavily."},{"problem":"Head movement blurs","solution":"Increase shutter and allow Auto ISO to rise."}],"sony":"Select Animal recognition; check the detected eye because fur and head angle can hide it.","fullFrame":"About 50–85mm gives similar framing; choose depth of field deliberately rather than converting exposure settings.","phone":"Use the main or optical portrait lens in good light; inspect artificial blur around whiskers and fur.","sources":[{"label":"Sony a6700: animal and bird eyes","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_about_eye_af.html"}]},{"id":"insects-in-flight","title":"Insects in flight","category":"wildlife","description":"Watch for a repeatable hover or landing route instead of chasing random movement.","tags":["insect","macro","action","hovering"],"difficulty":"Advanced","settings":{"mode":"M + Auto ISO","aperture":"f/5.6–8","shutter":"1/2000–1/4000 s","iso":"Auto · strong light needed","focus":"AF-C · Insect · Zone or Spot"},"lens":"70–200mm close-focusing lens or 90–100mm macro; additional optics help. Your 55mm allows wider attempts.","support":"Handheld with elbows supported where practical.","why":"Small subjects move quickly through a very shallow sharp zone. These bright-light starting ranges favour body detail; even a fast shutter may leave rapidly beating wings blurred.","steps":["Watch a flower or hovering position until the insect's route becomes predictable.","Prefocus near that distance, then track the insect as it approaches.","Take short bursts and inspect the body; refine distance and focus area before raising ISO limits."],"composition":["Include the flower as a destination and leave space along the approach.","Keep the background distant so the tiny subject remains visible."],"pack":["Close-focusing lens","Lens hood","Charged battery","Fast memory card"],"fixes":[{"problem":"Focus hunts","solution":"Prefocus near the expected distance and use a smaller area over the insect."},{"problem":"Body still blurs","solution":"Increase shutter or wait for a steadier hover."},{"problem":"ISO becomes excessive","solution":"Choose brighter light or photograph the insect after landing."}],"sony":"Recognition Target includes Insect. Recognition can fail on tiny subjects; Zone or Spot can guide acquisition.","fullFrame":"Depth of field and image scale change with distance and lens; retain action-based shutter timing.","phone":"Landing or resting insects are more reliable; flight challenges autofocus, reach and shutter control.","sources":[{"label":"Sony a6700: Insect recognition","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"},{"label":"Sony a6700: subject recognition operation","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_about_eye_af.html"}]},{"id":"birds-backlit","title":"Backlit birds","category":"wildlife","description":"Choose between luminous feather edges, a readable bird and a deliberate silhouette.","tags":["birds","backlight","rim light","silhouette"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/4–6.3 · lens permitting","shutter":"1/800–1/1600 s · perched","iso":"Auto · exposure compensation by test","focus":"AF-C · Bird · Spot or Tracking: Spot M"},"lens":"100–400mm actual APS-C focal length; additional telephoto generally needed.","support":"Handheld or supported position; hood fitted.","why":"Bright backgrounds may leave a bird darker than intended. These settings suit a perched subject; choose between interior detail and a silhouette rather than equalising every tone.","steps":["Position for rim light while keeping direct sun outside the lens.","Focus on the head and make a test to judge the bird and bright feather edges.","Adjust exposure compensation toward your intended detail or silhouette, checking highlights after each change."],"composition":["For a silhouette, seek a clear beak, eye line and separated body shape.","For rim light, place illuminated feathers against a darker distant background."],"pack":["Telephoto lens","Lens hood","Support","Lens cloth"],"fixes":[{"problem":"Bird lacks detail","solution":"Increase exposure cautiously or wait for softer light from the side."},{"problem":"Bright feather edges clip","solution":"Reduce exposure; accept darker interior tones if needed."},{"problem":"Hazy low contrast","solution":"Shade the lens and change angle slightly to reduce flare."}],"sony":"Backlight can hinder recognition; use Spot over the head when Bird detection struggles.","fullFrame":"Use focal length to match framing; compensate exposure for the same artistic intent and highlights.","phone":"Silhouettes work well; automatic HDR may brighten the bird against your intention.","sources":[{"label":"Sony a6700: recognition limitations","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_about_eye_af.html"},{"label":"Sony a6700: histogram display","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/201h_histogram.html"}]},{"id":"wildlife-low-light","title":"Wildlife in low light","category":"wildlife","description":"Wait for a pause and preserve detail without sacrificing essential shutter speed.","tags":["wildlife","dawn","dusk","low light"],"difficulty":"Advanced","settings":{"mode":"M + Auto ISO","aperture":"Widest usable · f/2.8–6.3","shutter":"1/250–1/800 s · settled subject","iso":"Auto · allow high ISO","focus":"AF-C · Animal or Bird"},"lens":"100–400mm actual APS-C telephoto; a brighter additional lens helps at distance.","support":"Beanbag, monopod or tripod; support cannot freeze the animal.","why":"As light fades, subject movement constrains exposure. These ranges suit pauses rather than running; a sharp noisy frame is more useful than a clean blurred one.","steps":["Open the aperture and settle your support before the subject pauses.","Set shutter for movement and check that Auto ISO provides sufficient brightness.","Inspect the eye; shorten shutter if needed or wait for better light."],"composition":["Let surrounding darkness simplify the frame instead of lifting every shadow.","Look for a small patch of sky light reaching the face."],"pack":["Telephoto lens","Stable support","Lens hood","Spare battery"],"fixes":[{"problem":"High ISO noise","solution":"Improve light or widen aperture; slow shutter only during a genuine pause."},{"problem":"Frame stays too dark","solution":"Check the Auto ISO ceiling; raise it or slow shutter only when appropriate."},{"problem":"AF fails repeatedly","solution":"Use a high-contrast feature and smaller focus area, or wait for better light."}],"sony":"Low light hinders recognition; verify eye sharpness instead of trusting a detection box.","fullFrame":"Keep shutter fast enough for movement; sensor size does not remove that requirement.","phone":"Night mode suits still subjects; moving wildlife often ghosts or blurs during multi-frame capture.","sources":[{"label":"Sony a6700: recognition limitations","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_about_eye_af.html"},{"label":"Nikon: exposure fundamentals","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/a-basic-look-at-the-basics-of-exposure"}]},{"id":"sunrise","title":"Sunrise","category":"landscape","description":"Keep the first colour in the sky and choose what the foreground contributes.","tags":["dawn","golden hour","sky","tripod"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; often 1/4–1/125 s","iso":"100","focus":"AF-S on a useful mid-distance feature"},"lens":"11 mm for a strong foreground; 16–55 mm to isolate the horizon.","support":"Tripod when the metered shutter is too slow for a sharp handheld frame.","why":"Sky colour often needs less exposure than the shaded ground. Decide whether to keep a silhouette or record a bracket for later blending.","steps":["Arrive before the sun and choose a definite subject.","Set ISO 100, meter the scene, then reduce exposure if important cloud detail clips.","Check near and far detail enlarged; bracket if one exposure cannot hold both."],"composition":["Use a path, bank or reflection to lead into the light.","Try a tighter frame when the foreground adds nothing."],"pack":["Tripod","Lens cloth","Spare battery"],"fixes":[{"problem":"White sky","solution":"Reduce exposure until the important coloured clouds retain detail; the sun itself may clip."},{"problem":"Black foreground","solution":"Accept a silhouette, or bracket a static scene instead of raising every exposure."},{"problem":"Soft grasses","solution":"Use a faster shutter and raise ISO if moving grasses must be crisp."}],"sony":"Shoot RAW. Use the playback histogram and highlight indication alongside the image; monitor brightness alone is unreliable.","fullFrame":"Use roughly 16–24 mm for a similar wide view. F-number still controls exposure normally; choose depth of field separately.","phone":"Tap the bright sky and lower exposure. HDR can help, but inspect moving leaves for blending artefacts.","sources":[{"label":"Sony — Capture Dynamic Landscapes","url":"https://www.sony.com/electronics/support/articles/00199911"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"sunset","title":"Sunset","category":"landscape","description":"Build a picture around the evening light rather than filling the frame with empty sky.","tags":["dusk","warm light","silhouette","landscape"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; review for movement","iso":"100–400","focus":"AF-S on the main subject"},"lens":"16–55 mm to arrange layers; 11 mm only when the foreground earns its space.","support":"Handheld in good light; tripod for the last colour.","why":"The setting sun changes the contrast faster than a fixed recipe can follow. Exposure compensation lets you preserve the colour while choosing how dark the land should feel.","steps":["Frame a recognisable shape before choosing exposure.","Take a test at f/8; protect textured clouds with a small negative adjustment if needed.","Stay after sunset and photograph the softer afterglow with a fresh exposure."],"composition":["Place a small silhouette where it separates clearly from the sky.","Turn away from the sun to look for side-lit trees or buildings."],"pack":["Lens hood","Tripod","Lens cloth"],"fixes":[{"problem":"Colour looks pale","solution":"Reduce exposure if channels are clipping; extra saturation cannot restore missing detail."},{"problem":"Flare hides the subject","solution":"Shift your position slightly and clean the front element."},{"problem":"Everything feels flat","solution":"Find side light or overlapping layers; settings cannot create a subject."}],"sony":"Use a consistent daylight white balance for a series if you want stable previews; RAW white balance remains editable.","fullFrame":"A longer full-frame focal length gives the same framing from the same position; no exposure multiplier is required.","phone":"Lock exposure on the sky, then reduce brightness gently. Avoid excessive digital zoom.","sources":[{"label":"Sony — Capture Dynamic Landscapes","url":"https://www.sony.com/electronics/support/articles/00199911"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"golden-hour-landscape","title":"Golden-hour landscape","category":"landscape","description":"Use low side light to reveal shape, texture and depth.","tags":["warm light","fields","trees","side light"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; target ≥1/125 s handheld","iso":"100–400","focus":"AF-S; check near and far detail"},"lens":"16–55 mm for flexible framing; 11 mm for a close foreground.","support":"Handheld; tripod if the frame includes static, finely detailed foreground.","why":"Low light direction matters more than a particular colour temperature. A moderate aperture balances detail with practical shutter speed on APS-C.","steps":["Walk until the light crosses the subject rather than hitting it straight on.","Start at f/5.6 or f/8 and check that the metered shutter suits wind and handholding.","Inspect the brightest textured surface and adjust exposure before shooting a series."],"composition":["Let shadows lead through the scene.","Exclude a bright patch at the frame edge if it steals attention."],"pack":["Lens hood","Spare battery","Optional tripod"],"fixes":[{"problem":"Wind-blurred leaves","solution":"Raise ISO to keep a faster shutter; a tripod only controls camera movement."},{"problem":"Near foreground is soft","solution":"Focus more carefully, step back, or use f/11 when extra depth is worth the tradeoff."},{"problem":"Too much orange","solution":"Use a neutral white balance as a starting point and warm it deliberately."}],"sony":"Keep SteadyShot on handheld. Turn it off for a rigid tripod setup, as Sony advises.","fullFrame":"At matching framing, reassess depth of field. You may choose a smaller aperture, with a corresponding shutter or ISO change.","phone":"Use the main camera and include a clear subject. HDR may lighten shadows more than intended.","sources":[{"label":"Sony — Capture Dynamic Landscapes","url":"https://www.sony.com/electronics/support/articles/00199911"},{"label":"Sony a6700 — SteadyShot","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_still_image_steadyshot.html"}]},{"id":"dramatic-clouds","title":"Dramatic clouds","category":"landscape","description":"Give the weather a clear role without losing texture in the brightest cloud.","tags":["storm","clouds","sky","contrast"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; target 1/125–1/500 s","iso":"100–400","focus":"AF-S on land or a defined distant edge"},"lens":"11 mm for a sweeping sky; 16–55 mm for a specific cloud and landscape relationship.","support":"Handheld in daylight; tripod as light falls.","why":"A bright cloud can clip even when most of the frame is dark. Judge the part of the sky that matters rather than trying to centre every histogram.","steps":["Find a land feature that gives the sky scale.","Expose a test, inspect bright cloud edges, and reduce exposure only as much as needed.","Wait for a shaft of light or a useful cloud opening, then recheck the exposure."],"composition":["Use a low horizon when the clouds carry the story.","Make the brightest cloud support your subject rather than compete with it."],"pack":["Lens hood","Rain cover","Lens cloth"],"fixes":[{"problem":"Cloud highlights vanish","solution":"Use less exposure or bracket if the land becomes unusably dark."},{"problem":"Land is lifeless","solution":"Wait for selective light or use a deliberate silhouette."},{"problem":"Sky is uneven with a polariser","solution":"Reduce polarisation or remove the filter, especially at 11 mm."}],"sony":"RAW gives useful latitude, but clipped highlight detail is not guaranteed to recover. Review the captured frame.","fullFrame":"Use a focal length about 1.5 times longer for matching a6700 framing. Meter exposure normally.","phone":"Tap the bright clouds and adjust exposure. Watch for heavy HDR halos around the skyline.","sources":[{"label":"Sony — Capture Dynamic Landscapes","url":"https://www.sony.com/electronics/support/articles/00199911"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"woodland","title":"Woodland","category":"landscape","description":"Separate one tree, path or patch of light from the surrounding clutter.","tags":["forest","trees","autumn","shade"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/4–8","shutter":"Target ≥1/125 s; verify","iso":"Auto 100–3200","focus":"AF-S on chosen trunk; AF-C for movement"},"lens":"16–55 mm, often 35–55 mm to exclude tangled edges.","support":"Handheld while exploring; tripod for still, low-light scenes.","why":"Woodland photographs fail more often through clutter than through exposure. A longer framing choice and careful camera position can create separation without extreme background blur.","steps":["Pick one trunk or bend in the path and remove distractions by moving sideways.","Choose f/5.6 and set ISO AUTO Min. SS to 1/125 s; verify the metered shutter.","Review the corners and bright gaps in the canopy before the next frame."],"composition":["Place the subject against a darker or more distant layer.","Try a vertical frame following the tree or path."],"pack":["Lens hood","Lens cloth","Optional polariser"],"fixes":[{"problem":"No obvious subject","solution":"Move closer or zoom in until one shape dominates."},{"problem":"Bright sky holes distract","solution":"Lower the framing or change position to hide them behind branches."},{"problem":"Leaves smear","solution":"Use a faster shutter; stabilisation cannot freeze foliage."}],"sony":"Auto ISO can use a slower shutter after reaching its ISO ceiling. Use M + Auto ISO when shutter speed must stay fixed; check exposure if the ceiling is reached.","fullFrame":"Choose focal length for framing, then reassess depth of field; stopping down may help layered trunks.","phone":"Avoid synthetic portrait blur on complex branches. Use the main camera and simplify the edges.","sources":[{"label":"Sony — Capture Dynamic Landscapes","url":"https://www.sony.com/electronics/support/articles/00199911"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"},{"label":"Sony a6700: ISO AUTO Min. SS","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0408H_ISO_auto_minimun_SS.html"}]},{"id":"misty-morning","title":"Misty morning","category":"landscape","description":"Let receding tones and a strong near silhouette create depth.","tags":["fog","mist","minimal","dawn"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; 1/125 s handheld target","iso":"100–800","focus":"AF-S on a contrast edge; MF if hunting"},"lens":"16–55 mm to layer trees; 11 mm only with a strong nearby shape.","support":"Tripod in dim dawn light; handheld once the shutter is adequate.","why":"Mist removes contrast and can fool the meter into rendering a bright scene too grey. Exposure should keep the intended lightness without erasing the nearest textures.","steps":["Find a dark foreground subject with lighter layers behind it.","Start near neutral compensation, then add a little exposure if the mist looks muddy.","Check the lens for condensation and refocus on a visible edge."],"composition":["Leave space around the silhouette so the mist can do the separating.","Avoid including too many competing trees."],"pack":["Lens cloth","Tripod","Weather cover"],"fixes":[{"problem":"Mist looks grey","solution":"Increase exposure cautiously and check the brightest mist for clipping."},{"problem":"Autofocus hunts","solution":"Use a distinct trunk edge or magnified manual focus."},{"problem":"Nothing looks sharp","solution":"Check for condensation before changing camera settings."}],"sony":"Focus Magnifier is useful for a distant edge when contrast is weak. Do not force the lens to its infinity endpoint.","fullFrame":"Matching perspective comes from the same position; use a longer focal length for a similar field of view.","phone":"Tap a foreground edge for focus and raise exposure slightly if needed. Avoid aggressive dehaze.","sources":[{"label":"Nikon — Photographing Mountains","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/tips-for-photographing-mountains"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"mountains","title":"Mountain layers","category":"landscape","description":"Choose between a foreground story and a tighter study of distant ridges.","tags":["mountains","ridges","distance","haze"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; target 1/125–1/500 s handheld","iso":"100–400","focus":"AF-S on the important ridge or foreground"},"lens":"16–55 mm for ridge layers; 11 mm with an intentional close foreground.","support":"Handheld in daylight; tripod for low light or repeatable framing.","why":"Distant ridges need less depth of field than a composition containing nearby rocks. Atmospheric haze limits distant detail regardless of how small you make the aperture.","steps":["Decide which ridge or foreground object is the subject.","Focus there at f/8 and inspect both the closest necessary detail and distant peaks.","Wait for side light or a clearing instead of trying to repair every hazy frame."],"composition":["Overlap ridges to make distance visible.","Include one small object for scale only if it stays readable."],"pack":["Lens hood","Lens cloth","Spare battery"],"fixes":[{"problem":"Mountains feel tiny","solution":"Zoom toward 55 mm and remove unhelpful foreground."},{"problem":"Distance is soft","solution":"Compare atmospheric shimmer and haze before blaming focus."},{"problem":"Foreground and peaks disagree","solution":"Move back, use f/11, or focus-stack a static scene with care."}],"sony":"Keep ISO low when the scene is still, but prioritise a sharp exposure when wind shakes the camera.","fullFrame":"Approximately 24–85 mm covers the standard-zoom framing range used here. Exposure is still metered normally.","phone":"Use an optical telephoto module if available for layers; heavy digital zoom reduces usable detail.","sources":[{"label":"Nikon — Photographing Mountains","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/tips-for-photographing-mountains"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"beach","title":"Beach and dunes","category":"landscape","description":"Use a clean shoreline or sand pattern to organise a bright, open scene.","tags":["coast","sand","sea","sunny"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; target 1/250–1/1000 s","iso":"100","focus":"AF-S on foreground structure"},"lens":"11 mm for a close dune or ripple pattern; 16–55 mm for shoreline details.","support":"Handheld by day; tripod for deliberate slow-water variations.","why":"Bright sand and water can pull automatic exposure away from your intention. Protect meaningful texture while accepting tiny sun glints when necessary.","steps":["Choose a clean line before walking through the foreground.","Start at f/8 and review sand highlights and the horizon.","Shoot a second frame with a different camera height to change the foreground scale."],"composition":["Use the shoreline as a diagonal entering the image.","Keep the horizon clear of awkward tangencies with heads, boats or posts."],"pack":["Lens hood","Lens cloth","Protective bag"],"fixes":[{"problem":"Sand looks grey","solution":"Add exposure gradually while retaining texture in bright areas."},{"problem":"Empty foreground","solution":"Move closer to a ripple, shell or footprint pattern."},{"problem":"Harsh blue band in sky","solution":"Reduce polarisation; ultra-wide coverage can make its effect uneven."}],"sony":"Keep the lens fitted in blowing sand. Use the on-screen level and review horizon placement.","fullFrame":"Use 16–24 mm for an ultra-wide view or 24–85 mm for a standard view. Recheck foreground depth of field.","phone":"Clean the lens and use the main camera. Tap exposure on textured sand, then check bright water.","sources":[{"label":"Sony — Capture Dynamic Landscapes","url":"https://www.sony.com/electronics/support/articles/00199911"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"snow-landscape","title":"Snow landscape","category":"landscape","description":"Make snow look bright while preserving its shape and surface detail.","tags":["snow","winter","white","cold"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; target ≥1/250 s for drifting snow","iso":"100–800","focus":"AF-S on a tree, track or contrast edge"},"lens":"16–55 mm for flexible framing; 11 mm for nearby tracks leading into the scene.","support":"Handheld; tripod for still dawn scenes.","why":"Snow is bright, but its shadows carry shape. A positive exposure adjustment can help when metering renders it grey; the right amount depends on the scene.","steps":["Take a neutral test frame at f/8.","If the snow is too grey, add exposure in small increments and inspect highlight texture.","Use a faster shutter for falling flakes or let them streak deliberately."],"composition":["Find one dark shape to anchor the frame.","Keep untouched snow clean by planning your route before walking in."],"pack":["Spare battery kept warm","Gloves","Dry lens cloth","Camera bag"],"fixes":[{"problem":"Snow is featureless white","solution":"Reduce exposure until textured snow reappears."},{"problem":"Snow is dull grey","solution":"Add compensation after checking the test frame."},{"problem":"Lens fogs indoors","solution":"Keep the cold camera bagged while it warms gradually."}],"sony":"RAW makes later white-balance adjustment straightforward. Avoid judging exposure from the screen brightness in brilliant snow.","fullFrame":"The same exposure decisions apply; no crop-factor correction is needed for ISO, shutter or f-number.","phone":"Raise exposure only after checking the preview. Preserve bright snow rather than relying entirely on HDR.","sources":[{"label":"Nikon — Shooting in Cold Weather","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/tips-for-shooting-in-cold-weather"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"landscape-bracket","title":"Landscape exposure bracket","category":"landscape","description":"Record a bright sky and a dark static foreground for a controlled HDR blend.","tags":["HDR","bracketing","sunrise","high contrast"],"difficulty":"Intermediate","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Varies across bracket","iso":"100, fixed","focus":"AF-S then lock focus / MF"},"lens":"11 mm or 16–55 mm; keep focal length unchanged through the set.","support":"Tripod strongly preferred; allow the camera to settle.","why":"Exposure bracketing captures brightness ranges that one frame may not hold. Keeping aperture, focus and composition fixed makes the frames easier to combine.","steps":["Use RAW, fixed ISO and f/8; test three frames at −2, 0 and +2 EV.","Check the dark frame for the brightest required detail and the bright frame for usable shadows.","Capture the sequence promptly, then inspect for movement before choosing a blend."],"composition":["Compose a photograph first; HDR cannot rescue a confused frame.","Keep moving water or leaves from crossing difficult skyline edges when possible."],"pack":["Tripod","Remote or bracket self-timer","Spare battery"],"fixes":[{"problem":"Ghosted branches","solution":"Use deghosting cautiously or choose one source exposure for the moving area."},{"problem":"Highlights still clip","solution":"Shift the bracket darker or expand its range based on the histogram."},{"problem":"Blend looks artificial","solution":"Use restrained tone mapping and preserve natural shadow depth."}],"sony":"Choose Cont. Bracket in Drive Mode and use the dedicated bracket self-timer. Keep ISO fixed.","fullFrame":"The same technique works. Choose aperture for the depth of field needed with your full-frame lens.","phone":"Built-in HDR merges automatically; manual bracket capture requires an app with exposure control and a steady phone.","sources":[{"label":"Sony a6700 — Drive Mode","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0407C_drive_mode.html"},{"label":"Sony a6700 — Bracket Settings","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0407G_bracket_setting.html"}]},{"id":"silky-waterfall","title":"Silky waterfall","category":"water","description":"Turn flowing water into soft lines while keeping the surrounding rocks crisp.","tags":["waterfall","long exposure","ND","river"],"difficulty":"Easy","settings":{"mode":"M / Manual","aperture":"f/5.6–8","shutter":"1/4–1 s","iso":"100","focus":"AF-S on rocks, then MF"},"lens":"16–55 mm for selecting a cascade; 11 mm with a meaningful foreground.","support":"Stable tripod and remote or self-timer.","why":"Shutter duration controls the amount of water blur. Use an ND filter when daylight is too bright for the desired shutter and aperture.","steps":["Compose and focus before fitting a strong ND filter.","Start at 1/2 s, f/8, ISO 100; adjust filter strength or shutter to match the light.","Inspect water highlights and compare a faster frame with a slower one."],"composition":["Find a stream line that carries the eye through the frame.","Keep empty bright sky out unless it contributes."],"pack":["Tripod","ND filter as needed","Remote or timer","Dry lens cloth"],"fixes":[{"problem":"Water is pure white","solution":"Reduce exposure or use a stronger ND; preserve the brightest textured flow."},{"problem":"Water becomes a blank smear","solution":"Shorten the shutter toward 1/4 s to restore texture."},{"problem":"Rocks are soft","solution":"Check tripod movement, focus and spray on the lens separately."}],"sony":"Turn SteadyShot off on the tripod. A two-second self-timer is adequate for a fixed shutter duration.","fullFrame":"Water blur depends on shutter duration, not sensor size. Choose aperture for the required depth of field.","phone":"A computational long-exposure mode may work, but fine foliage can develop merge artefacts; support the phone.","sources":[{"label":"Sony — Landscape and Flowing Water Techniques","url":"https://www.sony.com/electronics/support/articles/00047693"},{"label":"Sony a6700 — SteadyShot","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_still_image_steadyshot.html"}]},{"id":"frozen-waterfall","title":"Frozen waterfall spray","category":"water","description":"Show individual droplets and the energy of a fast cascade.","tags":["waterfall","splash","fast shutter","water"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/4–5.6","shutter":"1/1000–1/2000 s","iso":"Auto 100–6400","focus":"AF-C near the splash plane"},"lens":"16–55 mm, usually the longer end to isolate the strongest water shape.","support":"Handheld from a secure, dry position.","why":"Fast shutter speed reveals structure that a long exposure hides. The amount needed depends on water speed, distance and how large the droplets appear in the frame.","steps":["Choose a repeated splash and preframe the area.","Start at 1/1600 s and f/4; let ISO rise as needed.","Shoot a short burst, then enlarge a frame to decide whether to go faster."],"composition":["Use dark rock or shade behind bright droplets.","Leave room in the direction the spray travels."],"pack":["Lens hood","Rain cover","Dry lens cloth"],"fixes":[{"problem":"Droplets still streak","solution":"Increase shutter speed and open the aperture or allow more ISO."},{"problem":"White water clips","solution":"Apply negative compensation with Auto ISO and inspect highlights."},{"problem":"Only the background is sharp","solution":"Move the focus area onto water at the intended distance or prefocus manually."}],"sony":"Use mechanical shutter for rapidly moving water if electronic shutter produces distorted shapes.","fullFrame":"The same motion-freezing shutter is relevant at comparable framing. Sensor size does not replace shutter speed.","phone":"Use a short burst in bright light. Many phone apps do not give direct shutter control.","sources":[{"label":"Sony — Capture the Motion in Photographs","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-9-series/articles/00223372?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"seascape-motion","title":"Seascape with moving water","category":"water","description":"Use short flowing streaks to connect the foreground with the sea.","tags":["waves","coast","motion","long exposure"],"difficulty":"Intermediate","settings":{"mode":"M / Manual","aperture":"f/5.6–8","shutter":"1/4–1 s","iso":"100","focus":"AF-S on the foreground, then MF"},"lens":"11 mm for nearby leading streaks; 16–55 mm for a tighter shoreline.","support":"Tripod positioned clear of incoming waves.","why":"A brief long exposure can retain the direction of a wave. Timing matters as much as duration because incoming and receding water draw different patterns.","steps":["Observe several waves and choose a safe, stable position.","Start at 1/2 s, f/8 and ISO 100; add ND if required.","Trigger as water recedes, then check the pattern and repeat at 1/4 or 1 s."],"composition":["Give the water a route from a lower corner toward the subject.","Keep one clear rock or structure as an anchor."],"pack":["Tripod","ND filter as needed","Lens cloth","Protective cover"],"fixes":[{"problem":"Water looks shapeless","solution":"Shorten the shutter and time a stronger receding wave."},{"problem":"Tripod has shifted","solution":"Move to stable ground and recheck the framing between waves."},{"problem":"Bright foam clips","solution":"Reduce exposure without losing the intended motion effect; an ND can help."}],"sony":"Turn SteadyShot off on the tripod. Recheck focus after moving the camera or zooming.","fullFrame":"Keep shutter based on the wave effect. Around 16–24 mm gives a view similar to 11–16 mm on a6700.","phone":"Support the phone. Computational long exposure can blur waves pleasantly but offers less timing control.","sources":[{"label":"Sony — Landscape and Flowing Water Techniques","url":"https://www.sony.com/electronics/support/articles/00047693"},{"label":"Sony a6700 — SteadyShot","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_still_image_steadyshot.html"}]},{"id":"long-exposure-sea","title":"Minimal long-exposure sea","category":"water","description":"Smooth repeated waves into a quiet surface around a strong fixed subject.","tags":["sea","minimal","ND","long exposure"],"difficulty":"Intermediate","settings":{"mode":"M / Manual","aperture":"f/5.6–8","shutter":"10–30 s","iso":"100","focus":"AF-S before filter, then MF"},"lens":"16–55 mm to isolate a pier, post or headland; 11 mm for a broader setting.","support":"Rigid tripod with remote or timer.","why":"A longer exposure averages many wave positions into a softer surface. In daylight this usually requires a strong ND filter, with exposure based on a metered unfiltered frame.","steps":["Compose and focus without the ND, then record a good baseline exposure.","Fit the filter and multiply the baseline shutter by 2 for each filter stop.","Make a test and inspect brightness, filter colour and camera movement."],"composition":["Choose a fixed shape with enough visual weight to survive the simplified water.","Use generous empty space deliberately."],"pack":["Tripod","Strong ND filter","Lens cloth","Remote or timer"],"fixes":[{"problem":"Exposure is wrong","solution":"Check the actual ND strength and changing light, then adjust from the test frame."},{"problem":"Image is washed out","solution":"Check flare and light leakage around the filter holder."},{"problem":"Whole frame is soft","solution":"Lower the tripod, secure it and reduce wind vibration."}],"sony":"Turn SteadyShot Off. Beyond 30 seconds, use M/Bulb with Mechanical Shutter and built-in interval shooting Off. Set BULB Timer or use a compatible remote.","fullFrame":"The ND exposure calculation is unchanged. Match framing and choose aperture for depth of field.","phone":"A long-exposure app can approximate the effect through stacking; it may not behave like one optical exposure.","sources":[{"label":"Sony — Manual Exposure","url":"https://www.sony.com/electronics/support/articles/00267933"},{"label":"Sony — Landscape and Flowing Water Techniques","url":"https://www.sony.com/electronics/support/articles/00047693"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"},{"label":"Sony a6700: Bulb prerequisites","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0302C_bulb.html"},{"label":"Sony a6700: BULB Timer Settings","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_bulb_timer.html"}]},{"id":"reflections","title":"Calm-water reflections","category":"water","description":"Balance the real subject with its reflection and decide whether symmetry helps.","tags":["lake","reflection","symmetry","water"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; target 1/60–1/250 s for ripples","iso":"100–400","focus":"AF-S on the reflected subject or distant bank"},"lens":"16–55 mm for clean framing; 11 mm when foreground and sky both matter.","support":"Handheld if sharp; tripod for a still dawn scene.","why":"A reflection is an image of the distant subject, so focusing on the nearby water surface may be wrong. Gentle ripples need a shutter choice that matches the effect you want.","steps":["Find the best reflection before setting up; move a little to remove obstructions.","Focus on a clear reflected edge or the real subject and shoot at f/8.","Compare a faster frame preserving ripples with a slower frame smoothing them."],"composition":["Centre the dividing line if a deliberate mirror composition works.","Try filling the frame with only the reflected scene."],"pack":["Lens cloth","Optional tripod","Optional polariser"],"fixes":[{"problem":"Reflection disappears","solution":"Reduce polariser strength or remove it."},{"problem":"Reflection is soft","solution":"Focus on reflected detail, then check both subject and reflection."},{"problem":"Frame feels repetitive","solution":"Crop closer or include one asymmetric detail."}],"sony":"Use a small focus area to select the reflected detail rather than floating debris. Keep SteadyShot on handheld.","fullFrame":"The focusing principle stays the same. Check depth of field if nearby objects are also important.","phone":"Tap the reflected subject for focus. Keep the phone level and avoid over-brightening the sky.","sources":[{"label":"Nikon — Photographing Mountains and Reflections","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/tips-for-photographing-mountains"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"rain","title":"Rain and falling drops","category":"water","description":"Make rain visible by pairing backlight with a dark background.","tags":["rain","weather","drops","backlight"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/125 s streaks; 1/1000 s drops","iso":"Auto 100–6400","focus":"AF-S on scene; AF-C for people"},"lens":"16–55 mm, often 35–55 mm to isolate the rain and background.","support":"Handheld from shelter; protect the camera and lens.","why":"Rain needs contrast and light to become visible. Shutter speed changes its appearance, while background choice determines whether the drops stand out at all.","steps":["Find bright rain against a darker wall, tree or shaded street.","Start at 1/125 s for short streaks and f/2.8–4.","Compare a 1/1000 s frame; allow ISO to rise rather than unintentionally underexposing."],"composition":["Include a small umbrella or person to explain the weather.","Keep a bright lamp outside the frame if it causes distracting flare."],"pack":["Rain cover","Lens hood","Microfibre cloth"],"fixes":[{"problem":"Rain is invisible","solution":"Change angle to find backlight and a darker background."},{"problem":"Subject is blurred","solution":"Use a faster shutter if the subject moves; rain streaks may become shorter."},{"problem":"Frame looks foggy","solution":"Dry the front element and check condensation."}],"sony":"Use RAW and review colour under mixed street lighting. Weather resistance does not make the camera waterproof.","fullFrame":"For the same rain appearance, use similar shutter duration at comparable framing; adjust aperture for the look.","phone":"Avoid night mode for moving people unless blur is intentional. Tap a lit subject, not the darkest background.","sources":[{"label":"Sony — Capture the Motion in Photographs","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-9-series/articles/00223372?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"panning-cyclist","title":"Panning a cyclist","category":"water","description":"Keep the rider recognisable while the background records speed.","tags":["cycling","panning","motion","sports"],"difficulty":"Intermediate","settings":{"mode":"S / Shutter priority","aperture":"Metered; watch f/4–11","shutter":"1/30–1/60 s","iso":"100 in daylight; Auto if needed","focus":"AF-C tracking the rider"},"lens":"16–55 mm, around 35–55 mm for a rider crossing the view.","support":"Handheld with a smooth pivot; choose a safe position.","why":"Panning follows the subject during the exposure, reducing its movement across the sensor. Success depends on direction and tracking consistency, so expect a lower keeper rate.","steps":["Begin at 1/60 s and track the rider before releasing the shutter.","Keep rotating smoothly through a short burst and after it ends.","If the rider is sharp, try 1/30 s for stronger background blur."],"composition":["Use a clean background with colour or vertical lines to smear.","Leave space ahead of the rider."],"pack":["Camera strap","Lens hood","Optional ND in bright sun"],"fixes":[{"problem":"Everything is smeared","solution":"Start faster and concentrate on smooth matching of the rider’s movement."},{"problem":"Background is too sharp","solution":"Slow the shutter once the rider is consistently sharp."},{"problem":"Camera chooses f/22","solution":"Use an ND filter or find lower light to avoid unnecessary stopping down."}],"sony":"Use AF-C and a tracking focus area. Prefer mechanical shutter if electronic readout bends wheels or background lines.","fullFrame":"Keep the same starting shutter at similar framing and subject speed. Refine by the result.","phone":"Use a manual app if shutter control is available; computational processing may fight intentional blur.","sources":[{"label":"Sony — Capture the Motion in Photographs","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-9-series/articles/00223372?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"sports-action","title":"Sports action","category":"water","description":"Freeze a decisive gesture and keep focus on the person who matters.","tags":["sport","running","action","fast shutter"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/1000–1/2000 s","iso":"Auto 100–12800","focus":"AF-C; Human recognition and tracking"},"lens":"16–55 mm for nearby action; a longer telephoto is extra equipment for distant play.","support":"Handheld with space to follow the action.","why":"Motion blur and missed focus are different problems. A fast shutter controls the first; continuous focus and anticipation help with the second.","steps":["Start at 1/1600 s and f/2.8, then set Auto ISO for changing light.","Acquire the subject before the peak moment and use short bursts.","Enlarge faces and hands to assess shutter speed and focus separately."],"composition":["Leave room in the direction of travel or play.","Choose a background that does not merge with the athlete."],"pack":["Spare battery","Fast memory card","Lens hood"],"fixes":[{"problem":"Hands or feet streak","solution":"Use a faster shutter; accept the higher ISO if necessary."},{"problem":"Background is sharp instead","solution":"Improve subject acquisition and use a more selective tracking area."},{"problem":"High ISO is unavoidable","solution":"Move to better light or use a wider aperture; avoid sacrificing required shutter speed."}],"sony":"Select Human as the recognition target for athletes. Use mechanical shutter if electronic shutter distorts fast motion.","fullFrame":"Choose the shutter for motion, not crop factor alone. Use a suitable lens to achieve the intended framing.","phone":"Use burst shooting in good light. Long night-mode captures are poorly suited to fast action.","sources":[{"label":"Sony — Capture the Motion in Photographs","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-9-series/articles/00223372?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"light-trails","title":"Traffic light trails","category":"water","description":"Draw lines through a night scene while keeping the city structure sharp.","tags":["traffic","night","long exposure","city"],"difficulty":"Easy","settings":{"mode":"M / Manual","aperture":"f/5.6–8","shutter":"5–15 s","iso":"100","focus":"AF-S on distant structure, then MF"},"lens":"11 mm for sweeping roads; 16–55 mm to simplify a junction or curve.","support":"Stable tripod from a permitted pedestrian viewpoint.","why":"Exposure duration determines how far vehicles draw their trails. Ambient brightness and overlapping lights also accumulate, so longer is not always better.","steps":["Frame the road and focus before a promising stream of traffic arrives.","Start at 8 s, f/8 and ISO 100; check buildings and bright signs.","Time another frame to include a useful vehicle path without excessive overlap."],"composition":["Let the road lead toward a building or skyline anchor.","Keep trails from ending awkwardly at the subject."],"pack":["Tripod","Remote or timer","Lens hood"],"fixes":[{"problem":"Trails are too short","solution":"Wait for slower traffic or lengthen the exposure, compensating brightness as needed."},{"problem":"White mess at junction","solution":"Use a shorter exposure or a quieter traffic moment."},{"problem":"Buildings are noisy","solution":"Capture more light with a longer exposure if highlights allow; do not just lower ISO and underexpose."}],"sony":"Turn SteadyShot off on the tripod. Use manual focus after confirming a distant structure is sharp.","fullFrame":"Trail timing stays the same. Adjust focal length for the view and aperture for depth of field.","phone":"Use a tripod and a light-trail mode if available. Standard night mode may suppress some moving lights.","sources":[{"label":"Sony — Manual Exposure","url":"https://www.sony.com/electronics/support/articles/00267933"},{"label":"Sony a6700 — SteadyShot","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_still_image_steadyshot.html"}]},{"id":"fireworks","title":"Fireworks","category":"water","description":"Record the shape and colour of a burst without stacking too much light in one frame.","tags":["fireworks","night","celebration","long exposure"],"difficulty":"Intermediate","settings":{"mode":"M / Manual","aperture":"f/8–11 to start","shutter":"2–5 s to start","iso":"100","focus":"MF; verify on actual bursts"},"lens":"16–55 mm for flexible framing; 11 mm for fireworks with a large foreground setting.","support":"Tripod with remote release or timed exposures.","why":"Aperture and ISO strongly influence the brightness of each light trace. Shutter duration controls trail extent and burst overlap, while also changing the ambient exposure.","steps":["Start at ISO 100, f/11 and about 4 seconds with a loose frame.","Use early bursts to confirm focus enlarged; do not trust the infinity stop.","Adjust aperture for trace colour and brightness, then timing for shape and overlap."],"composition":["Leave space above the expected burst.","Include one foreground landmark to give the display a location."],"pack":["Tripod","Compatible remote or timer","Spare battery"],"fixes":[{"problem":"Traces are white","solution":"Stop down or reduce overlapping bursts; colour cannot be restored to clipped traces."},{"problem":"Burst is incomplete","solution":"Start earlier or extend timing around the burst."},{"problem":"Trails are soft","solution":"Refocus using magnification and recheck after zooming."}],"sony":"Turn SteadyShot off on the tripod. Disable Long Exposure NR when its processing delay would make you miss bursts.","fullFrame":"No crop-factor exposure adjustment is needed. Choose focal length for framing and check each display’s brightness.","phone":"Support the phone and lower exposure. Automatic night stacking can produce unpredictable burst shapes.","sources":[{"label":"Sony — Photographing a Fireworks Display","url":"https://www.sony.com/electronics/support/articles/00223375"}]},{"id":"city-blue-hour","title":"City at blue hour","category":"city","description":"Balance a luminous sky with the first lights in buildings and streets.","tags":["blue hour","cityscape","night","tripod"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; often 1–10 s","iso":"100","focus":"AF-S on a building edge, then lock"},"lens":"16–55 mm for a structured city view; 11 mm with a strong foreground.","support":"Tripod and timer; choose a stable surface.","why":"The useful balance between sky and street lighting lasts only a short time. A low-ISO tripod exposure lets static detail accumulate cleanly while you watch the changing light.","steps":["Compose before the lamps dominate the sky.","Start at f/8 and ISO 100, letting the meter suggest a shutter; adjust from the test frame.","Repeat as the sky deepens and compare both building detail and bright signs."],"composition":["Use a lit route to carry the eye toward the main building.","Keep verticals deliberate and clear distracting edges."],"pack":["Tripod","Remote or timer","Lens cloth"],"fixes":[{"problem":"Sky looks black","solution":"Shoot earlier or include less sky if the balance has passed."},{"problem":"Signs turn white","solution":"Reduce exposure or bracket the static scene."},{"problem":"People look ghosted","solution":"Accept motion as part of the scene or make a faster exposure with higher ISO."}],"sony":"Turn SteadyShot off on the tripod. Check the captured frame because a bright monitor can hide underexposure.","fullFrame":"Use 24–85 mm for comparable standard-zoom framing. Reassess depth of field if foreground detail is close.","phone":"Night mode works best on static scenes. Support the phone and inspect moving subjects for ghosting.","sources":[{"label":"Sony — Capture Dramatic Night Views","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-7-series/ilce-7/articles/00223367?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — SteadyShot","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_still_image_steadyshot.html"}]},{"id":"night-street-handheld","title":"Night street, handheld","category":"city","description":"Keep a moving street subject sharp while using the available light.","tags":["night","street","handheld","low light"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/1.8 at 11 mm; f/2.8 on zoom","shutter":"1/125–1/250 s for walking people","iso":"Auto 100–12800","focus":"AF-C; track the chosen person"},"lens":"16–55 mm f/2.8 for people; 11 mm f/1.8 for wider environmental scenes.","support":"Handheld, steady stance, SteadyShot on.","why":"Stabilisation helps camera shake but does not stop a person walking. Choose the motion-safe shutter first, then give the sensor as much light as the lens and scene allow.","steps":["Find a pool of light and frame a background before the subject arrives.","Start at 1/160 s, widest useful aperture and Auto ISO.","Review the face and bright signs; adjust exposure without making the moving subject too dark."],"composition":["Wait for a person to separate from the brightest sign.","Use reflections or doorways to organise the scene."],"pack":["Lens hood","Spare battery","Lens cloth"],"fixes":[{"problem":"Person is blurred","solution":"Use 1/250 s or faster if needed; accept more ISO."},{"problem":"Image is noisy","solution":"Find better light or use a wider aperture; lowering ISO alone does not capture more light."},{"problem":"Neon has no colour","solution":"Reduce exposure and protect the important sign. Faces may need a better-lit position."}],"sony":"Prefer mechanical shutter if artificial lighting produces bands. Test anti-flicker settings; results depend on the light source.","fullFrame":"Use a fast full-frame lens for the intended framing. Keep shutter based on subject movement.","phone":"Disable or shorten night mode for moving people; use the brightest available light.","sources":[{"label":"Sony — Capture Dramatic Night Views","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-7-series/ilce-7/articles/00223367?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — Anti-flicker Settings","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/201h_anti_flicker_setting.html"}]},{"id":"architecture","title":"Architecture and lines","category":"city","description":"Make the arrangement of edges, proportions and light intentional.","tags":["buildings","architecture","lines","perspective"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; target ≥1/125 s handheld","iso":"100–400","focus":"AF-S on a useful façade detail"},"lens":"16–55 mm for controlled proportions; 11 mm for tight spaces with careful edge placement.","support":"Handheld in daylight; tripod for precise repeatable framing.","why":"Tilting the camera changes how verticals converge in the image. Camera position and framing solve more perspective problems than changing focal length alone.","steps":["Decide between upright geometry and deliberate convergence.","Start at f/8, level the camera when needed and leave room for modest correction.","Inspect corners and edge sharpness before trying another camera height."],"composition":["Find a repeated pattern with one interruption.","Avoid letting half-cut posts or signs crowd the edges."],"pack":["Lens hood","Lens cloth","Optional tripod"],"fixes":[{"problem":"Building seems to fall back","solution":"Keep the camera more level, move farther away, or allow space for perspective correction."},{"problem":"Whole building feels cramped","solution":"Widen slightly or change position; do not assume every building needs the widest lens."},{"problem":"Dark shadows block up","solution":"Wait for softer light or bracket a static scene."}],"sony":"Use Grid Line Display and the level to help align the frame. Focus on actual façade detail.","fullFrame":"At the same position, matching field of view requires a longer focal length. Perspective still follows camera position and tilt.","phone":"Use grid lines and the main camera where possible. Ultra-wide edges can stretch nearby objects.","sources":[{"label":"Sony — Shoot Cityscapes While Traveling","url":"https://www.sony.com/electronics/support/articles/00223371"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"interiors","title":"Interiors and rooms","category":"city","description":"Show a space clearly while balancing windows with the room.","tags":["interior","rooms","windows","wide angle"],"difficulty":"Intermediate","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; often 1/4–2 s","iso":"100","focus":"AF-S on mid-room detail"},"lens":"11 mm for a room overview; 16–24 mm on the zoom for a more restrained view.","support":"Tripod where permitted; timer to avoid movement.","why":"Interior brightness can vary enormously between windows and walls. A stable camera allows low-ISO exposures and a bracket when a single frame cannot hold both.","steps":["Choose a viewpoint that explains the room and keep the camera close to level.","Focus at f/8, make a test and check window highlights.","Bracket if needed, keeping focus, aperture and camera position fixed."],"composition":["Use doorways and furniture to lead through the space.","Keep near furniture away from the extreme edges at 11 mm."],"pack":["Tripod","Remote or timer","Lens cloth"],"fixes":[{"problem":"Window is blank white","solution":"Reduce exposure for a second frame and blend carefully if window detail matters."},{"problem":"Mixed light looks strange","solution":"Choose a dominant light source; one white balance cannot neutralise every lamp and window."},{"problem":"Room feels distorted","solution":"Raise or lower the viewpoint and reduce tilt before relying on correction."}],"sony":"Turn SteadyShot off on the tripod. Use exposure bracketing rather than changing aperture between blend frames.","fullFrame":"Use a suitable full-frame wide lens; 16–18 mm approximates the 11 mm a6700 view. Check near-corner depth of field.","phone":"Keep the phone level and use HDR for static rooms. Watch edges and windows for heavy processing.","sources":[{"label":"Sony — Shoot Cityscapes While Traveling","url":"https://www.sony.com/electronics/support/articles/00223371"},{"label":"Sony a6700 — Bracket Settings","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0407G_bracket_setting.html"}]},{"id":"street-candid","title":"Candid street moment","category":"city","description":"Prepare the frame, then wait for a gesture that gives it meaning.","tags":["street","people","candid","daylight"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/4–5.6","shutter":"1/250–1/500 s","iso":"Auto 100–6400","focus":"AF-C; Human recognition / tracking"},"lens":"16–55 mm, often 23–35 mm for a person with surrounding context.","support":"Handheld and ready to follow movement.","why":"A clear background lets a small gesture become the subject. A moderately fast shutter and useful depth of field make fleeting moments less fragile.","steps":["Find a background with clean light and an obvious place for the subject.","Start at 1/320 s and f/5.6 with Auto ISO.","Follow the person and shoot when gesture, spacing and background align."],"composition":["Leave breathing room around hands, feet and the direction of gaze.","Wait for separation between overlapping people."],"pack":["Camera strap","Lens hood","Spare battery"],"fixes":[{"problem":"Moment is sharp but confusing","solution":"Simplify the background and wait for cleaner spacing."},{"problem":"Face is soft","solution":"Check whether focus missed or shutter was too slow; fix the actual cause."},{"problem":"Bright pavement clips","solution":"Adjust Auto ISO exposure compensation and keep the intended subject readable."}],"sony":"Use AF-C with Human recognition. A tracking area helps keep attention on the selected person rather than another face.","fullFrame":"Use roughly 35–50 mm for a similar everyday field of view. Match depth of field intentionally.","phone":"Use burst or rapid single frames in daylight. Avoid portrait-mode cutout blur for layered street scenes.","sources":[{"label":"Sony — Capture the Motion in Photographs","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-9-series/articles/00223372?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"market","title":"Markets and stalls","category":"city","description":"Combine colour, objects and human activity without losing the main subject.","tags":["market","travel","people","colour"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/160–1/320 s","iso":"Auto 100–6400","focus":"AF-C for people; AF-S for still goods"},"lens":"16–55 mm for both stall context and tighter details.","support":"Handheld; keep enough shutter speed for hands and people.","why":"Markets often mix shade, daylight and artificial lamps in one scene. A clear subject and controlled timing matter more than making every part equally bright.","steps":["Choose the seller, the produce or a transaction as the main story.","Start at 1/250 s and f/4, opening to f/2.8 in dim light.","Check faces, moving hands and colour under the dominant light."],"composition":["Use a pile of goods as a foreground frame without blocking the subject.","Capture a wide view and one precise detail as a pair."],"pack":["Camera strap","Lens hood","Spare battery"],"fixes":[{"problem":"Hands blur","solution":"Increase shutter speed and allow ISO to rise."},{"problem":"Too many colours compete","solution":"Zoom in or change position to create a simpler palette."},{"problem":"Lamps create bands","solution":"Try mechanical shutter and test anti-flicker controls; review an actual capture."}],"sony":"Anti-flicker Shoot. can help with detected 100/120 Hz flicker in mechanical still shooting, but cannot cure every LED source.","fullFrame":"Use a standard zoom with a useful maximum aperture. Shutter should still suit movement.","phone":"Tap the person or goods you want to expose. Avoid night-mode smearing during transactions.","sources":[{"label":"Sony — Shoot Cityscapes While Traveling","url":"https://www.sony.com/electronics/support/articles/00223371"},{"label":"Sony a6700 — Anti-flicker Settings","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/201h_anti_flicker_setting.html"}]},{"id":"museum","title":"Museums and galleries","category":"city","description":"Record a still exhibit cleanly within the venue’s photography rules.","tags":["museum","gallery","art","low light"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/2.8–4","shutter":"Metered; target 1/60–1/125 s handheld","iso":"Auto 100–6400","focus":"AF-S on important exhibit detail"},"lens":"16–55 mm for exhibits; 11 mm for permitted room views.","support":"Handheld with SteadyShot; use support only where allowed.","why":"A still exhibit permits slower shutter speeds than a moving person, provided the camera stays steady. Glass reflections and mixed lighting often limit the image more than ISO.","steps":["Check whether photography, tripods and flash are permitted.","Frame the exhibit, start at f/2.8–4 and inspect a test shot enlarged.","Adjust shutter or ISO to eliminate shake before making a tighter composition."],"composition":["Move sideways to keep your own reflection away from the exhibit.","Include a visitor for scale only when their movement and placement help."],"pack":["Lens cloth","Camera strap","Spare battery"],"fixes":[{"problem":"Fine detail is blurred","solution":"Increase shutter speed or brace the camera better."},{"problem":"Glass reflection dominates","solution":"Change angle and shade the lens without touching the display."},{"problem":"Bright display clips","solution":"Reduce exposure; keep detail in the exhibit rather than lifting every dark wall."}],"sony":"If silent electronic shutter is required, check for banding under gallery lights. Follow venue rules and test the resulting image.","fullFrame":"Use similar motion and handholding checks. Wider apertures give less depth of field at matching framing.","phone":"Use the main camera, avoid flash, and check whether night-mode processing alters fine artwork detail.","sources":[{"label":"Sony — Capture Dramatic Night Views","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-7-series/ilce-7/articles/00223367?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"travel-detail","title":"Travel details","category":"city","description":"Find one small clue that says something specific about the place.","tags":["travel","detail","texture","story"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/2.8–5.6","shutter":"Metered; target ≥1/125 s handheld","iso":"Auto 100–3200","focus":"AF-S on the defining detail"},"lens":"16–55 mm, often 35–55 mm to isolate a sign, handle, pattern or object.","support":"Handheld; steady yourself before taking a close frame.","why":"A detail image needs enough context to feel distinctive, but little enough clutter to stay clear. Aperture controls which surrounding clues remain legible.","steps":["Choose one object that carries a local story.","Frame at the longer end and focus exactly on its defining feature.","Compare f/2.8 with f/5.6 and choose how much context the image needs."],"composition":["Look for a repeated colour or shape that links the detail to its surroundings.","Check all four edges for accidental fragments."],"pack":["Lens cloth","Lens hood","Spare battery"],"fixes":[{"problem":"Nothing feels special","solution":"Find a relationship: worn texture against new material, a hand beside a tool, or colour repetition."},{"problem":"Important parts are soft","solution":"Stop down or align the subject more closely with the sensor plane."},{"problem":"Lens will not focus close enough","solution":"Move back within the lens’s focusing range and crop modestly."}],"sony":"Use AF-S and a small focus area for static details. The 16–55 mm is not a dedicated macro lens.","fullFrame":"Choose framing first, then reassess depth of field; close details may need a smaller aperture.","phone":"Keep within the phone lens’s close-focus distance. Automatic macro switching can change perspective and image quality.","sources":[{"label":"Sony — Shoot Cityscapes While Traveling","url":"https://www.sony.com/electronics/support/articles/00223371"},{"label":"Sony a6700 — Camera Controls","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/221h_list_of_menu_items_ilc2320.html"}]},{"id":"skyline","title":"City skyline","category":"city","description":"Arrange buildings into a readable rhythm and use light to separate their layers.","tags":["skyline","architecture","cityscape","distance"],"difficulty":"Easy","settings":{"mode":"A / Aperture priority","aperture":"f/5.6–8","shutter":"Metered; target 1/125–1/500 s in daylight","iso":"100–400","focus":"AF-S on a clear distant building edge"},"lens":"16–55 mm for a selected skyline; longer telephoto is extra gear for tight distant layers.","support":"Handheld in daylight; tripod at dusk.","why":"A skyline gains structure when the buildings have clear spacing and tonal separation. A wider frame is useful only when the extra surroundings support the subject.","steps":["Move until the key buildings separate from one another.","Start at f/8 and low ISO, then check haze, highlights and focus.","Try both a tighter frame and a wider contextual frame before leaving."],"composition":["Use water, a bridge or a clean strip of foreground to establish place.","Avoid cutting a major spire exactly against the frame edge."],"pack":["Lens hood","Lens cloth","Optional tripod"],"fixes":[{"problem":"Buildings look tiny","solution":"Zoom in or choose a closer permitted viewpoint."},{"problem":"Air looks hazy","solution":"Use the layers as atmosphere or return in clearer light; aperture cannot remove haze."},{"problem":"Lights overwhelm dusk","solution":"Reduce exposure or photograph earlier while the sky still balances them."}],"sony":"Use focus magnification or playback enlargement to confirm distant detail. Turn SteadyShot off once securely mounted.","fullFrame":"For a similar standard-zoom view use about 24–85 mm; longer focal lengths can isolate a distant cluster.","phone":"Use an optical telephoto module when available. Avoid pushing digital zoom beyond useful detail.","sources":[{"label":"Sony — Shoot Cityscapes While Traveling","url":"https://www.sony.com/electronics/support/articles/00223371"},{"label":"Sony a6700 — SteadyShot","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0414_still_image_steadyshot.html"}]},{"id":"city-rain","title":"City after rain","category":"city","description":"Use wet surfaces to connect a subject with the light around it.","tags":["rain","city","reflections","night"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/125–1/250 s for people","iso":"Auto 100–12800","focus":"AF-C for people; AF-S for static scene"},"lens":"16–55 mm for reflective streets; 11 mm near a foreground puddle.","support":"Handheld for moments; tripod with a separate slow exposure for static scenes.","why":"Wet surfaces can turn ordinary lights into useful shapes. A low viewpoint changes the reflection dramatically, while shutter choice decides whether people stay crisp.","steps":["Find a reflection that leads to a distinct subject.","Start at 1/160 s and f/2.8 for walking people, with Auto ISO.","Lower the camera and compare the reflection before changing lenses or settings."],"composition":["Keep the reflection connected visually to its source.","Wait for a clean silhouette crossing a bright reflected patch."],"pack":["Rain cover","Lens hood","Dry lens cloth"],"fixes":[{"problem":"Reflection is weak","solution":"Change height or angle; settings cannot restore a reflection that is absent."},{"problem":"Pedestrian blurs","solution":"Increase shutter speed and allow ISO to rise."},{"problem":"Wet highlights lose colour","solution":"Reduce exposure, keeping the important subject in usable light."}],"sony":"Check for LED banding and use mechanical shutter when appropriate. Dry the front element before judging contrast.","fullFrame":"Use a fast standard or wide lens; keep shutter based on movement, then choose aperture for the intended depth.","phone":"Use the main camera and control exposure on the reflections. Long night-mode captures may ghost walking people.","sources":[{"label":"Sony — Capture Dramatic Night Views","url":"https://www.sony.com/electronics/support/e-mount-body-ilce-7-series/ilce-7/articles/00223367?cpint=pro_en_00206559_shooting-tips"},{"label":"Sony a6700 — Anti-flicker Settings","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/201h_anti_flicker_setting.html"}]},{"id":"outdoor-portrait","title":"Outdoor portrait","category":"people","description":"A relaxed, single-person portrait in open shade with a soft background.","tags":["portrait","people","shade","bokeh"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/250 s","iso":"Auto","focus":"AF-C · eye"},"lens":"35–55 mm on your 16–55 mm; step back for natural facial proportions.","support":"Handheld; steady stance.","why":"A moderately fast shutter covers small movements while the aperture separates the person. Moving the background farther away often helps more than opening the aperture further.","steps":["Place the person in open shade facing a bright area of sky.","Focus on the nearer eye; take a test and enlarge it.","Check skin highlights, then change your position to simplify the background."],"composition":["Leave space in the direction of the gaze.","Keep bright branches and poles away from the head."],"pack":["16–55 mm lens","Lens hood","Optional white reflector"],"fixes":[{"problem":"Eyes are soft","solution":"Confirm the selected eye and try 1/500 s if the person moves."},{"problem":"Background is distracting","solution":"Increase subject-to-background distance or use 55 mm."},{"problem":"Face is too dark","solution":"Turn toward brighter open sky; increase exposure while checking skin highlights."}],"sony":"Set Recognition Target to Human and confirm the eye box follows your subject.","fullFrame":"Try roughly 50–85 mm for similar framing; check depth of field at your chosen aperture.","phone":"Use the normal or optical portrait camera; inspect hair edges if using simulated blur.","sources":[{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"},{"label":"Sony: portrait technique","url":"https://www.sony.com.au/electronics/support/articles/00206555"}]},{"id":"window-portrait","title":"Window-light portrait","category":"people","description":"A quiet indoor portrait beside a window, using available light.","tags":["portrait","window","indoor","natural light"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/2.8","shutter":"1/200 s","iso":"Auto","focus":"AF-C · eye"},"lens":"35–55 mm on the 16–55 mm; use 24–35 mm if the room is tight.","support":"Handheld; subject seated.","why":"The window acts as a large light source, while the room supplies gentle shadow. Keep enough shutter speed for breathing and small expressions.","steps":["Turn the face partly toward the window and switch off conflicting room lights.","Expose a test for the lit cheek; inspect the eye at full size.","Move a white card opposite the window to soften deep shadows if wanted."],"composition":["Include a small catchlight in the eyes.","Use the dark side of the room as a simple background."],"pack":["16–55 mm lens","White card","Optional sheer curtain"],"fixes":[{"problem":"ISO climbs sharply","solution":"Move closer to the window before slowing the shutter."},{"problem":"Sun makes hard patches","solution":"Diffuse direct sunlight or move out of its beam."},{"problem":"One eye is soft","solution":"Use f/4 or turn the face more squarely toward the camera."}],"sony":"Choose Human recognition; keep checking which eye the camera selects.","fullFrame":"A 50–85 mm lens gives similar coverage; a wider aperture needs more careful eye placement.","phone":"Use window light and tap the face; avoid a long night-mode capture if the person moves.","sources":[{"label":"Sony: window light portraits","url":"https://www.sony.co.uk/alphauniverse/alpha-academy/articles/top-tips-window-light-portraits"},{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"}]},{"id":"golden-hour-portrait","title":"Golden-hour portrait","category":"people","description":"Warm evening or morning light around a person, with controlled skin highlights.","tags":["portrait","golden hour","sunset","rim light"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/320 s","iso":"Auto","focus":"AF-C · eye"},"lens":"35–55 mm on your 16–55 mm for a comfortable working distance.","support":"Handheld.","why":"Low sun gives directional warmth and can outline hair. The face still needs enough light; exposing only for the sky can leave a difficult shadow recovery.","steps":["Place the sun behind or beside the person, outside the frame initially.","Find soft reflected light on the face; check a test for highlight detail.","Move slightly until flare is deliberate and the expression feels natural."],"composition":["Use a darker background to reveal a bright hair rim.","Watch the horizon so it does not cut across the face."],"pack":["16–55 mm lens","Lens hood","Optional reflector"],"fixes":[{"problem":"Face is muddy","solution":"Rotate toward reflected light or add a reflector."},{"problem":"Veiling flare washes everything","solution":"Shade the front element or change angle a little."},{"problem":"Skin has white patches","solution":"Reduce exposure or move the face out of direct sun."}],"sony":"Use Human recognition; backlighting can reduce AF contrast, so inspect the captured eye.","fullFrame":"Around 50–85 mm provides similar framing; keep the shutter suited to movement.","phone":"Tap the face and adjust exposure; HDR may struggle with moving hair.","sources":[{"label":"Sony: portrait technique","url":"https://www.sony.com.au/electronics/support/articles/00206555"},{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"}]},{"id":"environmental-portrait","title":"Environmental portrait","category":"people","description":"Show a person together with a meaningful place or activity.","tags":["portrait","story","workspace","travel"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/4–5.6","shutter":"1/250 s","iso":"Auto","focus":"AF-C · eye"},"lens":"16–24 mm on the 16–55 mm; reserve 11 mm for deliberately spacious compositions.","support":"Handheld; camera near subject height.","why":"A wider view explains what the person is doing. Moderate depth of field lets the setting contribute without requiring every distant detail to be sharp.","steps":["Choose one contextual object that tells the story.","Arrange the subject and that object clearly, then focus on the eye.","Check the frame edges and remove competing objects before shooting."],"composition":["Keep faces away from extreme wide-angle frame edges.","Let hands and tools connect visually to the activity."],"pack":["16–55 mm lens","Optional 11 mm lens","Lens cloth"],"fixes":[{"problem":"Person looks distorted","solution":"Step back and use a longer focal length."},{"problem":"Setting overwhelms the subject","solution":"Move closer or simplify the background."},{"problem":"Hands are blurred","solution":"Raise shutter speed to match the activity, such as 1/500 s."}],"sony":"Human recognition helps with the face; still inspect hands and the contextual object.","fullFrame":"Use roughly 24–35 mm for similar coverage; choose aperture for the required depth.","phone":"The normal camera is useful here; avoid artificial background blur when context matters.","sources":[{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"},{"label":"Sony: portrait technique","url":"https://www.sony.com.au/electronics/support/articles/00206555"}]},{"id":"group-portrait","title":"Group portrait","category":"people","description":"Several people arranged so every face has a fair chance of being sharp.","tags":["portrait","group","family","friends"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/5.6–8","shutter":"1/250 s","iso":"Auto","focus":"AF-C · selected face"},"lens":"24–35 mm on the 16–55 mm; step farther back rather than defaulting to 11 mm.","support":"Handheld or tripod.","why":"Depth differences between faces matter more than the number of people. A flatter arrangement reduces the aperture needed and makes focus more reliable.","steps":["Arrange faces in one plane or shallow, closely spaced rows.","Focus on a central face at a representative distance; test near and far faces.","Shoot several short sequences to catch open eyes and relaxed expressions."],"composition":["Keep outer faces away from wide-angle corners.","Leave enough space around feet and hands for a deliberate crop."],"pack":["16–55 mm lens","Optional tripod","Optional reflector"],"fixes":[{"problem":"Back row is soft","solution":"Bring rows closer, stop down, and recheck the focus distance."},{"problem":"Children are blurred","solution":"Try 1/500 s and accept a higher ISO."},{"problem":"Faces have patchy sunlight","solution":"Move the entire group into even open shade."}],"sony":"Select the intended person rather than accepting whichever face Human recognition chooses first.","fullFrame":"Use roughly 35–50 mm and reassess depth of field; f/8 may be a useful start.","phone":"Use the normal camera without portrait blur; take several frames for blinking.","sources":[{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"},{"label":"Sony: portrait technique","url":"https://www.sony.com.au/electronics/support/articles/00206555"}]},{"id":"children-playing","title":"Children at play","category":"people","description":"Freeze expressive moments while children move naturally in daylight.","tags":["children","action","family","movement"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/1000 s","iso":"Auto","focus":"AF-C · Human tracking"},"lens":"24–55 mm on the 16–55 mm; leave room for unexpected movement.","support":"Handheld; stable footing.","why":"Subject motion sets the shutter requirement even when camera stabilisation is active. A little extra depth of field helps when a child turns or moves toward you.","steps":["Choose a clean background and position yourself at the child’s eye level.","Start tracking before the expression or jump you want.","Use short bursts and check eyes and hands for motion blur."],"composition":["Leave space ahead of movement.","Look for interaction and gestures, not only a smile at the camera."],"pack":["16–55 mm lens","Spare battery","Lens hood"],"fixes":[{"problem":"Hands or feet smear","solution":"Increase to 1/1600–1/2000 s for faster action."},{"problem":"Focus follows the wrong person","solution":"Use a smaller tracking area on the intended child."},{"problem":"ISO becomes excessive","solution":"Find brighter light or open the aperture; keep a motion-safe shutter."}],"sony":"Use AF-C with Human recognition and a tracking area you can keep on the child.","fullFrame":"A standard zoom works well; the same movement still requires a fast shutter.","phone":"Use good light and burst capture; avoid night mode for fast movement.","sources":[{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"},{"label":"Sony: portrait technique","url":"https://www.sony.com.au/electronics/support/articles/00206555"}]},{"id":"event-candid","title":"Event candid","category":"people","description":"Natural expressions and interactions at an indoor gathering.","tags":["event","party","candid","people"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/2.8","shutter":"1/250 s","iso":"Auto","focus":"AF-C · Human"},"lens":"24–55 mm on the 16–55 mm; 16–24 mm for small groups.","support":"Handheld.","why":"People move even when standing still, so exposure must protect gestures and expressions. A wide aperture helps, but groups may need more depth of field.","steps":["Find a position where faces receive usable light rather than only ceiling shadows.","Watch interactions and begin focusing before the peak expression.","Review eyes, skin highlights and light bands after the first few frames."],"composition":["Include the second person when the interaction tells the story.","Avoid bright exit signs directly behind heads."],"pack":["16–55 mm lens","Spare battery","Spare card"],"fixes":[{"problem":"Faces blur","solution":"Raise shutter speed; stabilisation cannot freeze people."},{"problem":"Both people are not sharp","solution":"Use f/4 and arrange them at similar distances."},{"problem":"Bands cross the image","solution":"Try mechanical shutter and test a different shutter speed under those lights."}],"sony":"Select Human recognition. Check for LED banding before a long sequence; lighting behaviour varies.","fullFrame":"Use a standard fast zoom; depth of field still needs checking for multiple faces.","phone":"Use the normal camera in the brightest area; computational night capture can blur expressions.","sources":[{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"},{"label":"Sony: window light portraits","url":"https://www.sony.co.uk/alphauniverse/alpha-academy/articles/top-tips-window-light-portraits"}]},{"id":"silhouette-portrait","title":"Silhouette portrait","category":"people","description":"A clear human outline against a bright sky or window.","tags":["silhouette","portrait","sunset","shape"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/5.6","shutter":"1/250 s","iso":"Auto","focus":"AF-C · subject edge"},"lens":"24–55 mm on the 16–55 mm; choose the outline and background together.","support":"Handheld.","why":"The bright background supplies the exposure reference, while the subject becomes a shape. Distinct limbs and profiles communicate more than hidden facial detail.","steps":["Place the person against a clean bright area.","Reduce exposure until the background has colour and the person is dark.","Focus on a contrasting subject edge and inspect the outline."],"composition":["Separate arms from the torso and legs from each other.","Turn a face slightly into profile for a recognisable outline."],"pack":["16–55 mm lens","Lens hood","Optional tripod"],"fixes":[{"problem":"Face is too visible","solution":"Reduce exposure or remove light falling on the person."},{"problem":"Shape merges with scenery","solution":"Change camera height or move the person against open sky."},{"problem":"AF misses the dark face","solution":"Use a spot on a high-contrast edge, then confirm focus."}],"sony":"Human recognition may struggle with silhouettes; use a deliberate focus area when needed.","fullFrame":"Use roughly 35–85 mm for similar framing; background brightness determines exposure.","phone":"Tap the bright background and lower exposure; disable automatic shadow brightening if available.","sources":[{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"},{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"}]},{"id":"night-portrait","title":"Available-light night portrait","category":"people","description":"A person lit by a shop window or other continuous light after dark.","tags":["portrait","night","neon","available light"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/2.8","shutter":"1/200 s","iso":"Auto","focus":"AF-C · eye"},"lens":"24–55 mm on the 16–55 mm; the 11 mm f/1.8 suits a wider environmental portrait.","support":"Handheld; subject briefly still.","why":"Put light on the face before raising ISO. A bright background alone does not supply enough illumination for a sharp, clean portrait.","steps":["Place the face near a broad window or sign with usable light.","Check a test for eye sharpness and clipped illuminated signs.","Ask for a brief pause at the expression you want and shoot several frames."],"composition":["Use distant lights as background accents.","Keep strong coloured light intentional rather than mixing several colours across the face."],"pack":["16–55 mm lens","Optional 11 mm lens","Lens hood"],"fixes":[{"problem":"Face is noisy","solution":"Move into stronger light or use a wider aperture; do not simply darken the exposure."},{"problem":"Subject blurs","solution":"Raise shutter speed or ask for a steadier pose."},{"problem":"Sign dominates the frame","solution":"Reframe or change the subject-to-background angle."}],"sony":"Human recognition needs enough detail to lock; inspect the actual eye rather than trusting the box.","fullFrame":"A fast 35–85 mm lens can help collect light; check shallow focus carefully.","phone":"Ask the person to stay still; long night-mode exposures can blur small movements.","sources":[{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"},{"label":"Sony: window light portraits","url":"https://www.sony.co.uk/alphauniverse/alpha-academy/articles/top-tips-window-light-portraits"}]},{"id":"self-portrait","title":"Self-portrait","category":"people","description":"A deliberate portrait made with the camera supported and your position marked.","tags":["self portrait","timer","tripod","people"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/4–5.6","shutter":"1/250 s","iso":"Auto","focus":"MF at marked position"},"lens":"24–55 mm on the 16–55 mm; choose framing before setting the timer.","support":"Tripod and 10-second self-timer.","why":"Pre-focusing at a fixed position removes uncertainty while you move into place. Moderate depth of field gives room for small changes in posture.","steps":["Place a stand-in object at your face position, focus, then switch to MF.","Mark the position, activate the 10-second timer and return to the mark.","Review eye sharpness and framing; repeat with one pose change at a time."],"composition":["Compose around a gesture or activity instead of simply centring your face.","Leave a little extra crop room around the frame."],"pack":["Tripod","16–55 mm lens","Position marker","Stand-in object"],"fixes":[{"problem":"Face is soft","solution":"Check the stand-in was at eye distance and return to exactly that position."},{"problem":"Expression feels rushed","solution":"Prepare the pose before starting the next timer."},{"problem":"Tripod shot still blurs","solution":"Raise shutter speed for your movement and check the support."}],"sony":"The a6700 provides 2-, 5- and 10-second single-shot timer options; use 10 seconds here.","fullFrame":"Use roughly 35–85 mm and check that your chosen aperture covers pose movement.","phone":"Use a stable support and timer; the rear camera usually gives the best image quality.","sources":[{"label":"Sony a6700: self-timer","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0407_drivemode_selftimer.html"},{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"}]},{"id":"flowers","title":"Flowers with a soft background","category":"close","description":"Isolate a flower in gentle light while retaining its most expressive detail.","tags":["flowers","garden","close up","bokeh"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/250–1/500 s","iso":"Auto","focus":"AF-C · small spot"},"lens":"55 mm on the 16–55 mm for flower portraits; a macro lens is optional for tiny details.","support":"Handheld; tripod for a still flower.","why":"A nearby subject and distant background create separation. Wind can spoil detail even when the camera is stable, so watch petal movement.","steps":["Choose one flower with an uncluttered background.","Focus on the stamen or petal edge that carries the picture.","Wait for a lull in wind and check that the important detail is sharp."],"composition":["Lower the camera to the flower’s height.","Use a darker background behind translucent petals."],"pack":["16–55 mm lens","Lens cloth","Optional white card"],"fixes":[{"problem":"Flower looks soft","solution":"Raise shutter speed for wind; check the selected focus point."},{"problem":"Too little is sharp","solution":"Try f/5.6 and keep the important parts in one plane."},{"problem":"Cannot focus closer","solution":"Back away until focus works; use a macro lens for greater magnification."}],"sony":"Use a small focus area; Human recognition is unnecessary for this scene.","fullFrame":"A short telephoto gives similar isolation; closer focus reduces depth of field on either format.","phone":"Tap the flower and watch minimum focus distance; avoid artificial blur on delicate petals.","sources":[{"label":"Sony: flower photography","url":"https://www.sony.ca/en/electronics/support/articles/00206556"},{"label":"Sony: macro lenses and close focusing","url":"https://www.sony.co.uk/electronics/support/articles/00268247"}]},{"id":"insects-macro","title":"Insect macro detail","category":"close","description":"Record a small insect’s eye and structure at close range without disturbing it.","tags":["insects","macro","detail","nature"],"difficulty":"Advanced","settings":{"mode":"M + Auto ISO","aperture":"f/5.6–8","shutter":"1/500 s","iso":"Auto","focus":"AF-C spot or MF"},"lens":"A true macro lens is extra equipment; your 16–55 mm is for wider insect close-ups.","support":"Handheld with support; still subjects may suit a tripod.","why":"At high magnification the sharp zone is very thin and tiny movements matter. Subject alignment often improves the result more than using the smallest aperture.","steps":["Approach slowly and keep a comfortable working distance.","Align the camera with the insect’s eye and important body detail.","Take short sequences and inspect the eye; adjust focus or distance between attempts."],"composition":["Keep the eye clear of intervening leaves.","Leave space in the direction the insect faces."],"pack":["Macro lens if available","Optional diffused flash","Stable support"],"fixes":[{"problem":"Only one tiny area is sharp","solution":"Align the subject plane or try f/8–11 with more light."},{"problem":"Insect is too small","solution":"Use suitable macro optics; cropping cannot create missing detail."},{"problem":"Motion ruins detail","solution":"Use faster shutter or properly diffused flash; avoid chasing the insect."}],"sony":"The a6700 has an Insect recognition target; verify whether it identifies this insect reliably.","fullFrame":"Magnification and subject distance determine depth; a larger sensor does not remove the focus challenge.","phone":"Use a genuine macro camera if available; avoid shading or touching the insect.","sources":[{"label":"Sony: macro lenses and close focusing","url":"https://www.sony.co.uk/electronics/support/articles/00268247"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"},{"label":"Sony a6700: recognition targets","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/211h_recognition_target.html"}]},{"id":"food","title":"Food by window light","category":"close","description":"Give a plated meal shape and freshness using a simple window and careful framing.","tags":["food","table","window","still life"],"difficulty":"Easy","settings":{"mode":"A","aperture":"f/4–5.6","shutter":"Metered; tripod if slow","iso":"100–400","focus":"AF-S · main detail"},"lens":"35–55 mm for angled views; 24–35 mm for a flat lay on the 16–55 mm.","support":"Tripod or firm support.","why":"Directional soft light shows texture and gives food dimension. Aperture should keep the ingredient that matters sharp, not automatically blur half the plate.","steps":["Place the dish beside a window and turn off mixed room lighting.","Choose overhead or a low angle according to the food’s shape.","Focus on the main ingredient; check bright sauces and crockery for lost detail."],"composition":["Remove utensils that do not support the arrangement.","Leave a little space around the plate instead of accidental rim cuts."],"pack":["16–55 mm lens","White card","Clean cloth","Optional tripod"],"fixes":[{"problem":"Food looks flat","solution":"Move the light to the side or slightly behind."},{"problem":"Plate front is soft","solution":"Use f/5.6–8 or change camera angle to reduce depth."},{"problem":"Colour looks odd","solution":"Use one light type and set white balance from a neutral reference."}],"sony":"Use Focus Magnifier to check the selected food detail before a supported shot.","fullFrame":"A 50–85 mm lens suits angled views; check depth before opening the aperture.","phone":"Use the main camera and natural light; avoid a close ultra-wide view that stretches the plate.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"}]},{"id":"coffee","title":"Coffee & rising steam","category":"close","description":"Make a cup, crema and visible steam feel inviting in window light.","tags":["coffee","steam","food","cup"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/2.8–4","shutter":"1/250 s","iso":"Auto","focus":"AF-S · cup rim"},"lens":"35–55 mm on the 16–55 mm; focus within its normal close-focus range.","support":"Handheld or tripod.","why":"Steam needs light behind it and a darker background to show clearly. Shutter speed determines whether the steam looks defined or softly flowing.","steps":["Arrange the empty cup and background before pouring.","Place side or rear light across the rising steam and focus on the near rim.","Pour, shoot promptly, and inspect crema highlights and the steam pattern."],"composition":["Keep the handle and rim deliberately placed.","Use one supporting object, such as a spoon, to establish scale."],"pack":["16–55 mm lens","Dark background","White card","Clean cloth"],"fixes":[{"problem":"Steam disappears","solution":"Change the lighting angle and use a darker background."},{"problem":"Crema becomes white","solution":"Reduce exposure or soften the reflected light."},{"problem":"Cup rim is soft","solution":"Use f/5.6 or refocus on the rim; support the camera if slowing shutter."}],"sony":"A small AF-S area avoids the camera selecting the background through the steam.","fullFrame":"Use a standard or short telephoto lens; f/4 may help keep the rim in focus.","phone":"Use the main camera close enough for framing but beyond its focus limit; shoot a short sequence.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"},{"label":"Sony: photographing small objects","url":"https://www.sony-mea.com/en/electronics/support/e-mount-body-ilce-6000-series/ilce-6400a/articles/00223369"}]},{"id":"product","title":"Clean product photograph","category":"close","description":"A clear photograph of a medium-size object for a listing or record.","tags":["product","listing","catalogue","object"],"difficulty":"Easy","settings":{"mode":"M","aperture":"f/5.6–8","shutter":"Meter for the light","iso":"100","focus":"MF or AF-S"},"lens":"35–55 mm on the 16–55 mm; leave enough distance to avoid exaggerated perspective.","support":"Tripod; 2-second timer.","why":"Controlled light and repeatable framing make product details easy to judge. Low ISO is useful because a supported, static subject allows a longer exposure.","steps":["Clean the object and place it against a plain background.","Arrange a broad side light with white card on the shadow side.","Set exposure for important highlights; inspect detail and edges at full size."],"composition":["Keep the object level and leave even breathing space.","Photograph useful front, side and detail views at a consistent scale."],"pack":["16–55 mm lens","Tripod","Plain background","White card","Cleaning cloth"],"fixes":[{"problem":"Back edge is soft","solution":"Use f/8, adjust the angle or make a carefully aligned focus series."},{"problem":"White background turns grey","solution":"Light the background separately or adjust it without clipping the product."},{"problem":"Surface glare hides details","solution":"Move the light or camera; broad reflections can show shape better."}],"sony":"Use Focus Magnifier for precision; a timer reduces vibration from the shutter press.","fullFrame":"Use roughly 50–85 mm and assess depth of field across the object.","phone":"Use the main camera with stable support and even light; avoid digital zoom and portrait blur.","sources":[{"label":"Sony: photographing small objects","url":"https://www.sony-mea.com/en/electronics/support/e-mount-body-ilce-6000-series/ilce-6400a/articles/00223369"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"}]},{"id":"sculpture","title":"Sculpture & finished artwork","category":"close","description":"Show a three-dimensional piece’s form, finish and workmanship clearly.","tags":["sculpture","bust","art","product"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/5.6–8","shutter":"Meter for the light","iso":"100","focus":"MF · key feature"},"lens":"35–55 mm on the 16–55 mm; a wider view can distort a bust’s proportions.","support":"Tripod; self-timer.","why":"Raking light reveals modelling and finish, while a large light source softens harsh reflections. A record view and a dramatic view can serve different purposes.","steps":["Choose a neutral backdrop and camera height appropriate to the piece.","Move the light until facial planes or surface details read clearly.","Check near and far features, then capture an overall view and closer details."],"composition":["Use a three-quarter view when it reveals more form.","Keep the base fully intentional: include it cleanly or crop decisively."],"pack":["16–55 mm lens","Tripod","Neutral backdrop","White and black card"],"fixes":[{"problem":"Metallic finish looks flat","solution":"Introduce a controlled highlight and darker reflection."},{"problem":"Nose or rear detail is soft","solution":"Use f/8 or alter the viewing angle; consider a focus series."},{"problem":"Colour differs across images","solution":"Keep lighting and white balance fixed for the set."}],"sony":"Focus Magnifier helps distinguish missed focus from fine surface texture.","fullFrame":"A 50–85 mm view usually preserves proportions; choose aperture for the piece’s depth.","phone":"Use the main or optical telephoto camera; turn off synthetic portrait blur around intricate edges.","sources":[{"label":"Sony: photographing small objects","url":"https://www.sony-mea.com/en/electronics/support/e-mount-body-ilce-6000-series/ilce-6400a/articles/00223369"},{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"}]},{"id":"jewellery","title":"Jewellery & small reflective objects","category":"close","description":"Reveal shape and detail in a small polished item without distracting reflections.","tags":["jewellery","macro","metal","product"],"difficulty":"Advanced","settings":{"mode":"M","aperture":"f/5.6–8","shutter":"Meter for the light","iso":"100","focus":"MF · magnified"},"lens":"Your 16–55 mm suits an overall view; tiny detail needs a suitable macro lens or tested extension setup.","support":"Tripod; self-timer.","why":"Polished surfaces reflect the surroundings, so lighting means controlling what they reflect. Close-up depth of field can be too thin for the whole item.","steps":["Clean the item and build a simple arrangement of white and black cards.","Move the cards until reflections describe the shape without hiding details.","Magnify focus on the main feature; check whether a focus series is needed."],"composition":["Leave a clean edge against the background.","Use a slight angle when it makes thickness and construction readable."],"pack":["Tripod","Macro lens if needed","White and black cards","Microfibre cloth"],"fixes":[{"problem":"Metal is a white blob","solution":"Reduce or reshape the bright reflection; check exposure."},{"problem":"Item remains too small","solution":"Use greater optical magnification rather than extreme digital cropping."},{"problem":"Only one edge is sharp","solution":"Align the item more closely to the focus plane or stack a focus series."}],"sony":"Manual focus with Focus Magnifier is useful when AF grabs a reflection.","fullFrame":"True close-up work still needs appropriate magnification and careful depth control.","phone":"A dedicated macro mode may help; avoid computational blur and inspect tiny edges.","sources":[{"label":"Sony: macro lenses and close focusing","url":"https://www.sony.co.uk/electronics/support/articles/00268247"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"}]},{"id":"textures","title":"Textures & surface detail","category":"close","description":"Turn bark, stone, fabric or weathered paint into a clear graphic photograph.","tags":["texture","detail","abstract","pattern"],"difficulty":"Easy","settings":{"mode":"A","aperture":"f/5.6–8","shutter":"Metered; aim ≥1/125 s","iso":"Auto","focus":"AF-S · surface"},"lens":"35–55 mm on your 16–55 mm; use a macro lens only for smaller structures.","support":"Handheld or tripod.","why":"Low-angle light reveals relief through small shadows. Keeping the sensor roughly parallel to a flat surface helps the whole chosen area remain sharp.","steps":["Find one repeated texture with a small variation or interruption.","Move until side light makes the surface structure visible.","Square up the camera, focus carefully and inspect corners as well as the centre."],"composition":["Remove recognisable objects if you want a pure abstract.","Use the strongest diagonal or repeated line as the frame’s structure."],"pack":["16–55 mm lens","Optional tripod","Lens cloth"],"fixes":[{"problem":"Texture looks flat","solution":"Wait for more directional light or change the light angle."},{"problem":"Edges are soft","solution":"Align the camera more parallel and test f/8."},{"problem":"Image has no subject","solution":"Include one break in the repetition or make the pattern more consistent."}],"sony":"Use Focus Magnifier on a fine surface feature to check sharpness.","fullFrame":"A normal-to-short-telephoto lens works; match framing and check corner detail.","phone":"Use the main camera in side light; stay beyond its close-focus limit.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"}]},{"id":"still-life","title":"Simple still life","category":"close","description":"Arrange a few everyday objects into a deliberate composition in controlled light.","tags":["still life","tabletop","composition","objects"],"difficulty":"Easy","settings":{"mode":"M","aperture":"f/5.6","shutter":"Meter for the light","iso":"100","focus":"MF or AF-S"},"lens":"24–55 mm on the 16–55 mm according to arrangement size.","support":"Tripod; self-timer.","why":"A still subject gives time to solve composition and light before changing camera settings. The objects should form one readable arrangement rather than several unrelated focal points.","steps":["Choose three objects with a relationship in colour, shape or use.","Arrange them beside one light source and remove unnecessary props.","Focus on the visual centre, then inspect depth and highlight detail."],"composition":["Vary object height while keeping a clear focal point.","Check the shapes of the gaps as carefully as the objects."],"pack":["16–55 mm lens","Tripod","Plain surface","White card"],"fixes":[{"problem":"Everything feels equally important","solution":"Move the main object forward or give it stronger light."},{"problem":"Shadows are too dense","solution":"Bring a white card closer to the shadow side."},{"problem":"Rear object is soft","solution":"Try f/8 or bring the objects closer to one focus plane."}],"sony":"Use a small AF-S area or magnified MF; human subject recognition is unnecessary.","fullFrame":"Select focal length for perspective and framing; stopping down may be needed for the same arrangement.","phone":"A supported main camera works well; use exposure lock for consistent variations.","sources":[{"label":"Sony: photographing small objects","url":"https://www.sony-mea.com/en/electronics/support/e-mount-body-ilce-6000-series/ilce-6400a/articles/00223369"},{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"}]},{"id":"droplets","title":"Dew & water droplets","category":"close","description":"Make a still droplet stand out on a leaf, flower or pane of glass.","tags":["droplets","dew","macro","water"],"difficulty":"Intermediate","settings":{"mode":"M + Auto ISO","aperture":"f/5.6–8","shutter":"1/250 s","iso":"Auto","focus":"MF or small AF spot"},"lens":"55 mm for larger droplets on the 16–55 mm; a macro lens is needed for tiny close detail.","support":"Supported handheld or tripod.","why":"The focus can land on the droplet rim, its reflection or the surface beneath it. Choose which of those tells the picture and make that choice visible.","steps":["Find a well-positioned droplet with a clean background.","Move slowly until a useful reflection or bright edge appears.","Focus on the chosen feature and inspect it enlarged before changing composition."],"composition":["Use one dominant droplet with smaller supporting drops.","Keep bright background spots away from the droplet edge."],"pack":["16–55 mm lens","Macro lens if needed","Optional tripod","Lens cloth"],"fixes":[{"problem":"Lens cannot focus","solution":"Back off or use suitable macro optics."},{"problem":"Droplet is sharp but reflection is not","solution":"Refocus deliberately on the reflected image if that is your subject."},{"problem":"Leaf movement ruins focus","solution":"Wait for still air or raise shutter speed and use AF-C."}],"sony":"Focus Magnifier is useful for deciding whether the rim or reflected detail is sharp.","fullFrame":"Magnification and alignment matter more than format; check the chosen focus plane.","phone":"Use macro mode if available, protect the lens from moisture and avoid digital zoom.","sources":[{"label":"Sony: macro lenses and close focusing","url":"https://www.sony.co.uk/electronics/support/articles/00268247"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"}]},{"id":"backlight","title":"Backlit leaves & grasses","category":"creative","description":"Use light through translucent subjects to make ordinary plants glow.","tags":["backlight","leaves","grass","rim light"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/4","shutter":"1/500 s","iso":"Auto","focus":"AF-C · small spot"},"lens":"35–55 mm on the 16–55 mm; choose a distant, darker background.","support":"Handheld.","why":"Light passing through a leaf can reveal colour and structure. A darker background makes that brightness visible without requiring excessive contrast in editing.","steps":["Find leaves or grass with light behind them and shade beyond.","Move to keep direct sun just outside the frame.","Focus on the glowing edge or vein and check highlights and wind blur."],"composition":["Choose one clear shape instead of a tangled mass.","Let a few repeated stems create a rhythm around the main subject."],"pack":["16–55 mm lens","Lens hood","Lens cloth"],"fixes":[{"problem":"Everything looks hazy","solution":"Shade the lens or change angle to reduce flare."},{"problem":"Leaves lose colour","solution":"Reduce exposure until bright areas retain detail."},{"problem":"Subject blends into the background","solution":"Change camera height to put shade behind the bright subject."}],"sony":"A small AF area helps choose the intended leaf; check focus on the actual subject.","fullFrame":"A short telephoto can isolate details; the exposure principle is unchanged.","phone":"Tap the lit leaf and lower exposure if needed; keep the sun outside the frame initially.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"}]},{"id":"hard-light-shadows","title":"Hard light & graphic shadows","category":"creative","description":"Build a photograph around crisp shadows in strong directional light.","tags":["hard light","shadows","graphic","midday"],"difficulty":"Easy","settings":{"mode":"A","aperture":"f/5.6–8","shutter":"Metered; aim ≥1/250 s","iso":"100–400","focus":"AF-S · main plane"},"lens":"16–55 mm; use the focal length that simplifies the shadow geometry.","support":"Handheld.","why":"Strong light produces a clear boundary between bright and dark areas. That boundary can become the subject, even when the object casting it is ordinary.","steps":["Find a clean surface crossed by a distinctive shadow.","Choose a framing that gives the shadow a clear direction or shape.","Expose a test and retain texture in important bright surfaces."],"composition":["Watch corners where shadow lines enter or leave the frame.","Include a person or object only if it strengthens the shape."],"pack":["16–55 mm lens","Lens hood","Lens cloth"],"fixes":[{"problem":"Picture feels messy","solution":"Move closer or zoom in until fewer shadow lines remain."},{"problem":"Bright wall loses texture","solution":"Reduce exposure and review the highlights."},{"problem":"Shadow looks weak","solution":"Wait for harder light or choose a different surface and angle."}],"sony":"Use the captured histogram alongside the image; the histogram need not be centred.","fullFrame":"Use any lens that suits the geometry; choose aperture for the scene’s depth.","phone":"Tap the bright surface and adjust exposure; some automatic HDR may soften the intended contrast.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"}]},{"id":"low-key","title":"Low-key still life","category":"creative","description":"Keep a subject readable within a predominantly dark frame.","tags":["low key","dark","moody","still life"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/5.6","shutter":"Meter for the lit subject","iso":"100","focus":"MF or AF-S"},"lens":"35–55 mm on the 16–55 mm for a controlled tabletop view.","support":"Tripod; self-timer.","why":"A low-key photograph uses selective illumination and a dark environment. Merely underexposing everything can hide the subject without creating convincing shape.","steps":["Place the object against a dark background with one directional light.","Move or flag the light so it illuminates the subject more than the backdrop.","Expose for the important lit detail and inspect the transition into shadow."],"composition":["Keep one recognisable edge visible.","Let dark space support the object rather than divide it accidentally."],"pack":["16–55 mm lens","Tripod","Dark background","Black card"],"fixes":[{"problem":"Subject disappears","solution":"Add a small amount of reflected light to its edge."},{"problem":"Background is too bright","solution":"Increase separation and prevent light spilling onto it."},{"problem":"Image is noisy after editing","solution":"Capture a stronger usable exposure on the subject instead of heavily lifting an underexposed file."}],"sony":"Magnified MF helps place focus on the small illuminated area.","fullFrame":"Use the focal length you need; subject lighting creates the dark mood, regardless of sensor size.","phone":"Lock exposure on the lit detail; automatic night mode may brighten the intended dark areas.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"}]},{"id":"high-key","title":"High-key still life","category":"creative","description":"Create a light, airy photograph with pale tones and preserved subject detail.","tags":["high key","bright","white","still life"],"difficulty":"Intermediate","settings":{"mode":"A","aperture":"f/5.6","shutter":"Metered; tripod if slow","iso":"100","focus":"AF-S · main detail"},"lens":"24–55 mm on the 16–55 mm; keep the arrangement simple.","support":"Tripod or stable support.","why":"High-key starts with pale objects, a bright background and broad light. The result should feel luminous while important textured whites remain distinguishable.","steps":["Arrange pale objects on a light background beside broad soft light.","Add white card to soften shadows without removing all shape.","Increase exposure from the metered result as needed, checking textured whites."],"composition":["Use a small darker accent as a visual anchor.","Allow generous pale space around the main object."],"pack":["16–55 mm lens","White background","White card","Optional tripod"],"fixes":[{"problem":"Whites look grey","solution":"Raise exposure gradually while checking important highlights."},{"problem":"Subject edges vanish","solution":"Create a gentle shadow or add a dark card outside the frame."},{"problem":"White texture is clipped","solution":"Reduce exposure or lower the light contrast."}],"sony":"Review the captured image and histogram; a bright distribution is expected, but texture still matters.","fullFrame":"Use a similar field of view; light placement and exposure control remain the main tools.","phone":"Tap the subject and increase exposure carefully; avoid aggressive beauty or smoothing filters.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"}]},{"id":"intentional-camera-motion","title":"Intentional camera movement","category":"creative","description":"Turn trees, a shoreline or colour bands into an expressive abstract.","tags":["ICM","abstract","camera movement","blur"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/8","shutter":"0.3–1 s","iso":"100","focus":"AF-S, then MF"},"lens":"16–55 mm; start around 24–35 mm with simple vertical or horizontal forms.","support":"Handheld for a deliberate smooth sweep.","why":"During a long exposure, movement draws the scene across the sensor. Direction, speed and pauses determine whether recognisable structure remains.","steps":["Choose a simple arrangement of colour and strong lines.","Set the exposure; use shade or an ND filter if daylight is too bright.","Begin a smooth sweep before releasing the shutter, then compare several speeds."],"composition":["Follow vertical trunks or a horizontal shoreline for the first attempts.","Keep one dominant colour relationship rather than including the whole scene."],"pack":["16–55 mm lens","Optional ND filter","Lens cloth"],"fixes":[{"problem":"It only looks accidentally shaky","solution":"Use a more consistent direction and cleaner scene."},{"problem":"All structure disappears","solution":"Shorten the exposure or slow the sweep."},{"problem":"Frame is overexposed","solution":"Add ND or work in lower light; keep the desired shutter duration."}],"sony":"Try SteadyShot Off for deliberate sweeps, then restore it for ordinary handheld shooting.","fullFrame":"The same shutter approach works; the field of view changes how far forms travel across the frame.","phone":"A manual slow-shutter app may help; computational long-exposure modes can render movement differently.","sources":[{"label":"Nikon: intentional movement and autumn colour","url":"https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/autumn-impressions-tips-for-photographing-fall-color"}]},{"id":"abstract-reflections","title":"Abstract reflections","category":"creative","description":"Use rippled water, glass or polished metal to transform familiar shapes.","tags":["abstract","reflection","water","glass"],"difficulty":"Easy","settings":{"mode":"M + Auto ISO","aperture":"f/5.6","shutter":"1/250 s","iso":"Auto","focus":"AF-S · reflected detail"},"lens":"35–55 mm on your 16–55 mm for selecting a small part of the reflection.","support":"Handheld.","why":"A reflection supplies colour and structure that changes with viewpoint and surface movement. Framing tightly can remove the clues that make the source too obvious.","steps":["Find one striking colour or shape reflected in a simple surface.","Move slowly to see how the reflection changes, then choose a small area.","Focus on the reflected detail and test shutter speed for the desired ripple sharpness."],"composition":["Use distorted lines as the main structure.","Try excluding the horizon and the object being reflected."],"pack":["16–55 mm lens","Lens cloth","Optional tripod"],"fixes":[{"problem":"Reflection is dull","solution":"Change viewing angle or wait for stronger light on the reflected subject."},{"problem":"Ripples are smeared","solution":"Increase shutter speed to freeze their pattern."},{"problem":"Surface dirt is sharper than the reflection","solution":"Refocus on the reflected image rather than the surface."}],"sony":"Use a small AF area or MF when autofocus selects glass or surface debris.","fullFrame":"A short telephoto helps isolate a pattern; focus distance may be farther than the reflecting surface.","phone":"Tap the reflected subject; avoid a polariser if the reflection is what you want to retain.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"}]},{"id":"minimalist-scene","title":"Minimalist scene","category":"creative","description":"Give one small subject enough quiet space to become unmistakable.","tags":["minimalism","negative space","composition","simple"],"difficulty":"Easy","settings":{"mode":"A","aperture":"f/5.6–8","shutter":"Metered; aim ≥1/125 s","iso":"100–400","focus":"AF-S · subject"},"lens":"16–55 mm; zoom and reposition until the background becomes simple.","support":"Handheld; tripod in low light.","why":"Minimalism depends on selection and placement more than a particular lens. Empty space works when its colour, texture and proportion support the subject.","steps":["Find one isolated object against a consistent background.","Move to eliminate stray marks and decide how much space the subject needs.","Focus on the subject and check every edge for small distractions."],"composition":["Place the subject where the space feels intentional.","Compare one centred frame with one strongly off-centre frame."],"pack":["16–55 mm lens","Optional tripod","Lens cloth"],"fixes":[{"problem":"The subject is too weak","solution":"Increase its contrast, size or separation from the background."},{"problem":"Empty area feels accidental","solution":"Change its proportion and remove unrelated details."},{"problem":"Small subject is soft","solution":"Use precise focus and enough shutter speed; inspect it enlarged."}],"sony":"A small focus area gives more control than allowing the camera to choose from a large empty scene.","fullFrame":"Match the required field of view; minimalism does not require a wide lens.","phone":"Use the main camera and crop only moderately; inspect empty areas for processing artefacts.","sources":[{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"},{"label":"Sony a6700: Focus Magnifier","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0405_focus_magni.html"}]},{"id":"black-white","title":"Black & white with intent","category":"creative","description":"Build the picture from light, shape and texture rather than relying on colour.","tags":["black and white","monochrome","contrast","texture"],"difficulty":"Easy","settings":{"mode":"A","aperture":"f/5.6–8","shutter":"Metered; suit movement","iso":"Auto","focus":"AF-S or AF-C as needed"},"lens":"11 mm or 16–55 mm; choose framing for the subject rather than the monochrome effect.","support":"Handheld or tripod to suit the light.","why":"Colours that look distinct can become similar grey tones. Look for differences in brightness, edges and light direction before converting the image.","steps":["Choose a scene with clear light, shadow or texture.","Preview it in monochrome while retaining a RAW file.","Check whether the subject separates from the background without its colour."],"composition":["Use one strong line or luminous area to lead attention.","Avoid assuming every cloudy scene will become dramatic in black and white."],"pack":["Chosen lens","Lens hood","Optional tripod"],"fixes":[{"problem":"Subject blends into the background","solution":"Change viewpoint or lighting; do not rely only on conversion."},{"problem":"Image looks flat","solution":"Find stronger tonal separation rather than pushing contrast indiscriminately."},{"problem":"Highlights become empty","solution":"Reduce exposure and protect important bright texture."}],"sony":"Creative Look BW provides a monochrome preview; retain RAW for later colour and tonal choices.","fullFrame":"The same tonal decisions apply; lens choice follows the intended perspective and framing.","phone":"Preview with a monochrome filter if helpful and retain an original when the camera app allows it.","sources":[{"label":"Sony a6700: Creative Look","url":"https://helpguide.sony.net/ilc/2320/v1/en/contents/0411B_creative_look.html"},{"label":"Sony: lighting and its effects","url":"https://www.sony.com/electronics/support/articles/00267922"}]},{"id":"sunstar","title":"Sunstar through an edge","category":"creative","description":"Make a small, partially hidden sun form a controlled starburst in a wider scene.","tags":["sunstar","starburst","sun","landscape"],"difficulty":"Intermediate","settings":{"mode":"A","aperture":"f/11","shutter":"Metered for highlights","iso":"100","focus":"AF-S or MF · scene"},"lens":"Your 11 mm or 16–24 mm on the 16–55 mm; star shape depends on the lens.","support":"Tripod if shutter becomes slow.","why":"A small aperture can make a point light form diffraction rays. Partially hiding the sun reduces its apparent size and helps control the burst and flare.","steps":["Compose on the screen with the sun mostly behind a tree, wall or ridge.","Move a few centimetres until a small bright sliver appears.","Check exposure and flare, then compare f/8 and f/11 for the best compromise."],"composition":["Make the burst support an existing composition.","Keep flare spots away from important subject detail."],"pack":["Wide lens","Lens cloth","Optional tripod"],"fixes":[{"problem":"No defined star appears","solution":"Hide more of the sun and test a smaller aperture."},{"problem":"Whole image loses fine detail","solution":"Use f/8 if the burst remains acceptable; smaller apertures trade detail for rays."},{"problem":"Flare dominates","solution":"Clean the lens and alter the angle or sun position."}],"sony":"Inspect a captured frame; the aperture used for live viewing may not show the final starburst clearly.","fullFrame":"Try f/11–16 as a starting range, with the same diffraction and flare trade-offs.","phone":"Most phones have fixed apertures, so a classic adjustable-aperture sunstar may be unavailable.","sources":[{"label":"Sony: backlighting and sunstars","url":"https://www.sony.co.uk/alphauniverse/alpha-academy/articles/top-tips-capturing-backlit-portraits"}]},{"id":"panorama","title":"Panorama for later stitching","category":"creative","description":"Capture a consistent sequence when one frame cannot include the whole view.","tags":["panorama","stitching","landscape","wide"],"difficulty":"Intermediate","settings":{"mode":"M","aperture":"f/5.6–8","shutter":"Meter, then lock","iso":"100","focus":"MF · fixed distance"},"lens":"24–35 mm on your 16–55 mm for a straightforward first stitched panorama.","support":"Tripod with a level pan; careful handheld also works.","why":"Consistent exposure, focus and overlap make neighbouring frames easier to join. Nearby objects reveal viewpoint changes more readily than distant scenery.","steps":["Meter the brightest important area, then lock exposure, focus, zoom and white balance.","Photograph overlapping frames with about 30–40% overlap, keeping the camera level.","Check coverage and sharpness before leaving; merge the sequence later in your editor."],"composition":["Use vertical frames for more height and cropping room.","Leave extra space at the top and bottom for the stitched crop."],"pack":["16–55 mm lens","Optional tripod","Spare card"],"fixes":[{"problem":"Visible brightness bands","solution":"Use fixed settings and avoid changing light during the sequence."},{"problem":"Nearby objects do not align","solution":"Avoid close foreground or use a suitable panoramic head."},{"problem":"Moving people duplicate","solution":"Wait for a clearer scene or repair the overlap during editing."}],"sony":"Shoot separate still frames using fixed exposure and MF; assemble them in your editing software.","fullFrame":"Choose a similar field of view and maintain the same settings across the series.","phone":"Built-in panorama mode is convenient; rotate steadily and check for moving-subject distortions.","sources":[{"label":"Adobe: photographing frames for a panorama","url":"https://www.adobe.com/learn/photoshop/web/photoshop-panorama"}]}];
window.PFG_PHOTO_CREDITS = [{"category":"night","author":"Nadine Marfurt","url":"https://unsplash.com/photos/milky-way-over-a-mountain-reflected-in-water-8CunQ9GcUwo","license":"Unsplash License","licenseUrl":"https://unsplash.com/license","file":"images/night.jpg","alt":"The Milky Way above a pointed mountain and dark ridges reflected in still water."},{"category":"landscape","author":"paul mocan","url":"https://unsplash.com/photos/mountains-during-golden-hour-QnOdvmndfu4","license":"Unsplash License","licenseUrl":"https://unsplash.com/license","file":"images/landscape.jpg","alt":"An orange sunset behind layers of blue mountains and a dark foreground hillside."},{"category":"water","author":"Joshua Todi","url":"https://unsplash.com/photos/a-majestic-waterfall-flows-through-a-lush-forest-bkCbBjDz5_I","license":"Unsplash License","licenseUrl":"https://unsplash.com/license","file":"images/water.jpg","alt":"A broad waterfall pours into a river surrounded by dense green forest."},{"category":"wildlife","author":"Siegfried Poepperl","url":"https://unsplash.com/photos/a-robin-bird-perched-on-a-thin-branch-uH893VXm3q0","license":"Unsplash License","licenseUrl":"https://unsplash.com/license","file":"images/wildlife.jpg","alt":"A small orange-breasted bird perched on a thin branch among bare twigs."},{"category":"city","author":"Josh Hild","url":"https://unsplash.com/photos/city-street-scene-on-a-rainy-night-sDQHl4AeDzM","license":"Unsplash License","licenseUrl":"https://unsplash.com/license","file":"images/city.jpg","alt":"Streetlights and building lights reflected on a rain-soaked city street at blue hour."},{"category":"people","author":"Jake Heidecker","url":"https://unsplash.com/photos/silhouette-of-person-standing-during-sunset-X91OLW261HI","license":"Unsplash License","licenseUrl":"https://unsplash.com/license","file":"images/people.jpg","alt":"A person's side-profile silhouette against an orange and gold sunset above dark hills."},{"category":"close","author":"Sixteen Miles Out","url":"https://unsplash.com/photos/a-coffee-cup-sitting-on-top-of-a-table-next-to-a-window-ICLAIcyswYQ","license":"Unsplash License","licenseUrl":"https://unsplash.com/license","file":"images/close.jpg","alt":"A textured ceramic coffee cup and saucer on a wooden table in soft window light."},{"category":"creative","author":"Amal K Raju","url":"https://unsplash.com/photos/abstract-architectural-lines-with-light-and-shadow-qaO04vmpMd8","license":"Unsplash License","licenseUrl":"https://unsplash.com/license","file":"images/creative.jpg","alt":"Angular white architectural forms and dark shadows beneath high windows in black and white."}];
